// ============================================================================
// 2. JSON Pointer Utilities (RFC 6901)
// ============================================================================

/**
 * Resolves a value from a data model using a JSON pointer path (e.g. "/selectedWarehouse").
 */
export function getValueByPointer(dataModel: Record<string, any>, pointer: string): any {
  if (!pointer || typeof pointer !== 'string') return undefined;
  const path = pointer.startsWith('/') ? pointer.slice(1) : pointer;
  if (!path) return dataModel;

  const parts = path.split('/');
  let current: any = dataModel;

  for (const part of parts) {
    if (current === null || current === undefined) return undefined;
    const unescapedPart = part.replace(/~1/g, '/').replace(/~0/g, '~');
    current = current[unescapedPart];
  }

  return current;
}

/**
 * Sets a value at a JSON pointer path immutably or by structured cloning.
 */
export function setValueByPointer(
  dataModel: Record<string, any>,
  pointer: string,
  value: any
): Record<string, any> {
  if (!pointer || typeof pointer !== 'string') return dataModel;
  const path = pointer.startsWith('/') ? pointer.slice(1) : pointer;
  if (!path) return typeof value === 'object' && value !== null ? value : dataModel;

  const parts = path.split('/').map((p) => p.replace(/~1/g, '/').replace(/~0/g, '~'));
  const clone = JSON.parse(JSON.stringify(dataModel || {}));

  let current = clone;
  for (let i = 0; i < parts.length - 1; i++) {
    const key = parts[i];
    if (typeof current[key] !== 'object' || current[key] === null) {
      current[key] = {};
    }
    current = current[key];
  }

  const lastKey = parts[parts.length - 1];
  current[lastKey] = value;
  return clone;
}

/**
 * Recursively resolves JSON pointer references (`{ path: "/..." }`) in action event context
 * against the surface's current dataModel.
 */
export function resolveActionContext(
  contextObj: Record<string, any> | undefined,
  dataModel: Record<string, any>
): Record<string, any> {
  if (!contextObj || typeof contextObj !== 'object') return {};

  const resolved: Record<string, any> = {};
  for (const [key, val] of Object.entries(contextObj)) {
    if (val && typeof val === 'object') {
      if (typeof val.path === 'string') {
        resolved[key] = getValueByPointer(dataModel, val.path);
      } else {
        resolved[key] = resolveActionContext(val, dataModel);
      }
    } else {
      resolved[key] = val;
    }
  }

  return resolved;
}

// ============================================================================
// 3. A2UI Payload Ingestion, Standalone Normalization & Extraction Helper
// ============================================================================

/**
 * Checks if an object is a standalone Vega-Lite specification.
 */
function isVegaLiteSpecObject(obj: any): boolean {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  if (typeof obj.$schema === 'string' && obj.$schema.toLowerCase().includes('vega')) {
    return true;
  }
  if (obj.mark && (obj.encoding || obj.data || obj.layer)) {
    return true;
  }
  return false;
}

/**
 * Checks if an object is a standalone GoogleMap definition without a surface wrapper.
 */
function isStandaloneMapObject(obj: any): boolean {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const compType = obj.component || obj.type;
  if (compType === 'GoogleMap' || compType === 'Map') return true;
  if (
    obj.center &&
    typeof obj.center === 'object' &&
    (typeof obj.center.lat === 'number' || typeof obj.center.lng === 'number') &&
    (Array.isArray(obj.markers) || Array.isArray(obj.pins) || typeof obj.zoom === 'number')
  ) {
    return true;
  }
  return false;
}

/**
 * Checks if an object is a single A2UI component node (e.g. { component: "Badge", ... }).
 */
function isStandaloneComponentNode(obj: any): boolean {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  // Exclude Legacy A2UI card objects (which use top-level buttons/choices/options without properties/props/children)
  if (
    !obj.properties &&
    !obj.props &&
    !obj.children &&
    (Array.isArray(obj.buttons) || Array.isArray(obj.choices) || Array.isArray(obj.options))
  ) {
    return false;
  }
  const compType = obj.component || obj.type;
  if (typeof compType === 'string' && KNOWN_A2UI_WIDGET_TYPES.has(compType)) {
    return true;
  }
  return false;
}

/**
 * Normalizes standalone Vega-Lite specs, standalone Map objects, or raw component
 * objects/arrays into a standard A2UI v0.9.1 surface object so they render as live
 * interactive components instead of raw JSON code blocks.
 */
export function normalizeStandaloneA2UIPayload(obj: any): any | null {
  if (!obj || typeof obj !== 'object') return null;

  // 1. Standard A2UI surface envelope
  if (
    obj.mimeType === 'application/a2ui+json' ||
    Array.isArray(obj.messages) ||
    obj.createSurface ||
    obj.updateComponents ||
    obj.updateDataModel ||
    obj.deleteSurface ||
    (obj.surfaceId && (obj.components || obj.rootId || obj.dataModel))
  ) {
    return obj.mimeType === 'application/a2ui+json' && obj.data ? obj.data : obj;
  }

  // 2. Standalone Vega-Lite chart specification
  if (isVegaLiteSpecObject(obj)) {
    const chartTitle =
      typeof obj.title === 'string'
        ? obj.title
        : obj.title?.text || 'Vega-Lite Visualization';
    return {
      surfaceId: 'vega-chart-surface',
      title: chartTitle,
      rootId: 'auto-vega-chart',
      components: [
        {
          id: 'auto-vega-chart',
          component: 'VegaChart',
          properties: {
            title: chartTitle,
            description: obj.description || '',
            spec: obj,
          },
        },
      ],
    };
  }

  // 3. Standalone GoogleMap object
  if (isStandaloneMapObject(obj)) {
    const props = obj.properties || obj;
    return {
      surfaceId: obj.id || 'google-map-surface',
      title: props.title || 'Geographic Map Preview',
      rootId: obj.id || 'auto-google-map',
      components: [
        {
          id: obj.id || 'auto-google-map',
          component: 'GoogleMap',
          properties: {
            title: props.title || 'Geographic Map Preview',
            center: props.center || { lat: 37.7749, lng: -122.4194 },
            zoom: props.zoom ?? 10,
            markers: props.markers || props.pins || [],
          },
        },
      ],
    };
  }

  // 4. Single standalone A2UI component object
  if (isStandaloneComponentNode(obj)) {
    const compType = obj.component || obj.type;
    const compId = obj.id || `auto-${compType.toLowerCase()}-1`;
    return {
      surfaceId: `${compType.toLowerCase()}-surface`,
      title: obj.properties?.title || obj.title || `${compType} Preview`,
      rootId: compId,
      components: [
        {
          ...obj,
          id: compId,
          component: compType,
        },
      ],
      dataModel: obj.dataModel || {},
    };
  }

  // 5. Object with `components` array but no `surfaceId`
  if (Array.isArray(obj.components) && obj.components.length > 0 && obj.components.some(isStandaloneComponentNode)) {
    return {
      surfaceId: obj.surfaceId || 'a2ui-components-surface',
      title: obj.title || 'A2UI Component Surface',
      rootId: obj.rootId,
      components: obj.components,
      dataModel: obj.dataModel || {},
    };
  }

  // 6. Array of A2UI messages or array of standalone components
  if (Array.isArray(obj) && obj.length > 0) {
    if (
      obj.some(
        (item) =>
          item &&
          typeof item === 'object' &&
          (item.createSurface || item.updateComponents || item.updateDataModel || item.deleteSurface)
      )
    ) {
      return { messages: obj };
    }
    if (obj.every(isStandaloneComponentNode)) {
      return {
        surfaceId: 'a2ui-component-group',
        title: 'A2UI Components',
        components: obj.map((item, idx) => ({
          ...item,
          id: item.id || `auto-comp-${idx + 1}`,
          component: item.component || item.type,
        })),
      };
    }
  }

  return null;
}

/**
 * Checks whether an object resembles an A2UI v0.9.1 message, surface container,
 * or standalone A2UI widget/chart/map payload.
 */
export function isA2UIv09Payload(obj: any): boolean {
  return normalizeStandaloneA2UIPayload(obj) !== null;
}

/**
 * Attempts to parse or repair a raw JSON string from an A2UI code fence,
 * handling trailing commas or token-truncated component arrays.
 */
function tryParseOrRepairA2UIJson(rawBlock: string, isExplicitA2UIFence: boolean): any | null {
  const trimmed = rawBlock.trim();
  if (!trimmed) return null;

  // 1. Standard JSON.parse
  try {
    return JSON.parse(trimmed);
  } catch {
    // Continue to repair strategies
  }

  // 2. Strip trailing commas before } or ]
  try {
    const withoutTrailingCommas = trimmed.replace(/,\s*([}\]])/g, '$1');
    return JSON.parse(withoutTrailingCommas);
  } catch {
    // Continue
  }

  // 3. Repair token-truncated A2UI payload if it contains A2UI surface markers
  const looksLikeA2UI =
    isExplicitA2UIFence ||
    trimmed.includes('"createSurface"') ||
    trimmed.includes('"updateComponents"') ||
    trimmed.includes('"surfaceId"');
  if (!looksLikeA2UI) return null;

  const componentsIdx = trimmed.indexOf('"components"');
  if (componentsIdx !== -1) {
    // Walk backwards from the end to find the last complete component object `}`
    let searchPos = trimmed.length;
    while (searchPos > componentsIdx) {
      const lastBrace = trimmed.lastIndexOf('}', searchPos - 1);
      if (lastBrace <= componentsIdx) break;
      const candidatePrefix = trimmed.slice(0, lastBrace + 1).replace(/,\s*$/, '');

      // Compute exact unclosed bracket/brace stack outside string literals
      const openStack: string[] = [];
      let inStr = false;
      let esc = false;
      for (let i = 0; i < candidatePrefix.length; i++) {
        const ch = candidatePrefix[i];
        if (esc) {
          esc = false;
          continue;
        }
        if (ch === '\\' && inStr) {
          esc = true;
          continue;
        }
        if (ch === '"') {
          inStr = !inStr;
          continue;
        }
        if (!inStr) {
          if (ch === '{') openStack.push('}');
          else if (ch === '[') openStack.push(']');
          else if (ch === '}' || ch === ']') openStack.pop();
        }
      }

      if (!inStr && openStack.length > 0) {
        const autoSuffix = openStack.reverse().join('');
        try {
          const parsed = JSON.parse(candidatePrefix + autoSuffix);
          if (normalizeStandaloneA2UIPayload(parsed)) {
            return parsed;
          }
        } catch {
          // Try previous brace
        }
      }
      searchPos = lastBrace;
    }
  }

  return null;
}

/**
 * Extracts A2UI payloads from message strings or raw objects.
 * Supports direct JSON objects, message array containers, or markdown fenced code blocks.
 */
export function extractA2UIPayloads(
  content: string | any
): { textWithoutA2UI: string; surfaces: any[] } {
  if (!content) {
    return { textWithoutA2UI: '', surfaces: [] };
  }

  // 1. Direct object
  if (typeof content === 'object') {
    const normalized = normalizeStandaloneA2UIPayload(content);
    if (normalized) {
      return { textWithoutA2UI: '', surfaces: [normalized] };
    }
    return { textWithoutA2UI: '', surfaces: [] };
  }

  if (typeof content !== 'string') {
    return { textWithoutA2UI: String(content), surfaces: [] };
  }

  const trimmed = content.trim();

  // 2. Direct JSON string
  if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
    try {
      const parsed = JSON.parse(trimmed);
      const normalized = normalizeStandaloneA2UIPayload(parsed);
      if (normalized) {
        return { textWithoutA2UI: '', surfaces: [normalized] };
      }
      if (Array.isArray(parsed) && parsed.some(isA2UIv09Payload)) {
        return {
          textWithoutA2UI: '',
          surfaces: parsed.map((p) => normalizeStandaloneA2UIPayload(p) || p),
        };
      }
    } catch {
      // Continue to fence parsing
    }
  }

  // 3. Strip any unclosed ```a2ui or ```json block that was truncated before a subsequent ```a2ui fence
  const sanitizedContent = content.replace(
    /```(?:a2ui|json)\b(?:(?!```(?=[ \t]*(?:\r?\n|$)))[\s\S])*?(?=(?:^|\r?\n)[ \t]*```a2ui\b)/gi,
    ''
  );

  // 4. Fenced code blocks ```a2ui or ```json (closing fence must be at a line boundary, never matching ```" inside a JSON string)
  const surfaces: any[] = [];
  const fenceRegex = /```(json|a2ui)?[ \t]*\r?\n?([\s\S]*?)```(?=[ \t]*(?:\r?\n|$))/gi;
  let remainingText = sanitizedContent;
  let match: RegExpExecArray | null;

  while ((match = fenceRegex.exec(sanitizedContent)) !== null) {
    const fenceLang = (match[1] || '').toLowerCase();
    const isExplicitA2UIFence = fenceLang === 'a2ui';
    const rawBlock = match[2]?.trim();
    if (!rawBlock) {
      if (isExplicitA2UIFence) {
        remainingText = remainingText.replace(match[0], '');
      }
      continue;
    }

    const parsed = tryParseOrRepairA2UIJson(rawBlock, isExplicitA2UIFence);
    if (parsed) {
      const normalized = normalizeStandaloneA2UIPayload(parsed);
      if (normalized) {
        surfaces.push(normalized);
        remainingText = remainingText.replace(match[0], '');
        continue;
      }
    }

    // Never leave broken raw ```a2ui blocks in the markdown text if explicitly tagged as a2ui
    if (isExplicitA2UIFence) {
      remainingText = remainingText.replace(match[0], '');
    }
  }

  // 5. Handle trailing unclosed ```a2ui block at the end of a message (e.g., streaming or max_output_tokens cutoff)
  const unclosedA2uiMatch = remainingText.match(/```a2ui\b([\s\S]*)$/i);
  if (unclosedA2uiMatch) {
    const rawUnclosed = (unclosedA2uiMatch[1] || '').trim();
    const repaired = tryParseOrRepairA2UIJson(rawUnclosed, true);
    if (repaired) {
      const normalized = normalizeStandaloneA2UIPayload(repaired);
      if (normalized) {
        surfaces.push(normalized);
      }
    }
    remainingText = remainingText.replace(unclosedA2uiMatch[0], '');
  }

  return {
    textWithoutA2UI: remainingText.trim(),
    surfaces,
  };
}

