/**
 * Generates an inline SVG data URI placeholder image for carousel slides when
 * no external image URL is supplied or when an external URL fails to load.
 */
function buildSlidePlaceholderDataUri(title: string, subtitle?: string, idx = 0): string {
  const palettes = [
    { start: '#312e81', mid: '#4338ca', end: '#0f172a', accent: '#818cf8' },
    { start: '#064e3b', mid: '#047857', end: '#0f172a', accent: '#34d399' },
    { start: '#4c1d95', mid: '#6d28d9', end: '#0f172a', accent: '#c084fc' },
    { start: '#7c2d12', mid: '#b45309', end: '#0f172a', accent: '#fbbf24' },
  ];
  const pal = palettes[idx % palettes.length];
  const safeTitle = (title || 'A2UI Slide')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .slice(0, 28);
  const safeSub = (subtitle || 'Interactive Blueprint')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .slice(0, 36);

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="200" viewBox="0 0 400 200">
    <defs>
      <linearGradient id="bg-${idx}" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="${pal.start}"/>
        <stop offset="50%" stop-color="${pal.mid}"/>
        <stop offset="100%" stop-color="${pal.end}"/>
      </linearGradient>
    </defs>
    <rect width="400" height="200" fill="url(#bg-${idx})"/>
    <circle cx="340" cy="40" r="70" fill="${pal.accent}" fill-opacity="0.14"/>
    <circle cx="60" cy="170" r="85" fill="${pal.accent}" fill-opacity="0.1"/>
    <path d="M0 150 Q 120 110 220 145 T 400 125 L 400 200 L 0 200 Z" fill="#0d1117" fill-opacity="0.45"/>
    <rect x="20" y="20" width="84" height="22" rx="11" fill="#0d1117" fill-opacity="0.6" stroke="${pal.accent}" stroke-opacity="0.5"/>
    <text x="62" y="35" fill="${pal.accent}" font-family="sans-serif" font-size="10" font-weight="bold" text-anchor="middle">A2UI v0.9.1</text>
    <text x="20" y="138" fill="#ffffff" font-family="sans-serif" font-size="16" font-weight="bold">${safeTitle}</text>
    <text x="20" y="160" fill="#cbd5e1" font-family="sans-serif" font-size="11">${safeSub}</text>
  </svg>`;

  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

/**
 * Material & Basic Text component with typography variants.
 */
function RenderText({
  props,
  dataModel,
}: {
  props: Record<string, any>;
  dataModel: Record<string, any>;
}) {
  let content = props.text ?? props.content ?? props.value ?? '';
  if (props.text?.path) {
    content = getValueByPointer(dataModel, props.text.path) ?? content;
  } else if (typeof content === 'object' && content !== null) {
    content = JSON.stringify(content);
  }

  const variant = props.variant || 'body1';
  switch (variant) {
    case 'h1':
      return <h1 className="text-2xl leading-8 font-bold text-white my-1">{content}</h1>;
    case 'h2':
      return <h2 className="text-xl leading-7 font-bold text-white my-1">{content}</h2>;
    case 'h3':
      return <h3 className="text-lg leading-7 font-semibold text-white my-1">{content}</h3>;
    case 'h4':
      return <h4 className="text-base leading-6 font-medium text-gray-200 my-0.5">{content}</h4>;
    case 'h5':
      return <h5 className="text-sm leading-5 font-medium text-gray-300 my-0.5">{content}</h5>;
    case 'subtitle1':
    case 'subtitle2':
      return <p className="text-sm leading-5 text-indigo-300 font-medium my-0.5">{content}</p>;
    case 'caption':
      return <span className="text-xs leading-4 text-gray-400 italic block">{content}</span>;
    case 'code': {
      const cleanCode = String(content ?? '')
        .replace(/^```(?:json|a2ui|[a-zA-Z0-9_-]*)?[ \t]*\r?\n?/i, '')
        .replace(/\r?\n?[ \t]*```[ \t]*$/i, '');
      return (
        <pre className="p-3 rounded bg-[#0d1117] border border-[#30363d] text-sm leading-5 font-mono text-emerald-300 overflow-x-auto whitespace-pre-wrap my-1">
          {cleanCode}
        </pre>
      );
    }
    case 'body2':
      return <p className="text-sm leading-5 text-gray-300 my-0.5">{content}</p>;
    case 'body1':
    default:
      return <p className="text-base leading-6 text-gray-200 my-0.5">{content}</p>;
  }
}

/**
 * Material & Basic Badge component.
 */
function RenderBadge({ props }: { props: Record<string, any> }) {
  const label = props.label ?? props.text ?? props.value ?? 'Badge';
  const color = (props.color || props.variant || 'indigo').toLowerCase();

  let colorClasses = 'bg-indigo-500/20 text-indigo-300 border-indigo-500/40';
  if (color === 'emerald' || color === 'green' || color === 'success') {
    colorClasses = 'bg-emerald-500/20 text-emerald-300 border-emerald-500/40';
  } else if (color === 'amber' || color === 'yellow' || color === 'warning') {
    colorClasses = 'bg-amber-500/20 text-amber-300 border-amber-500/40';
  } else if (color === 'red' || color === 'error' || color === 'critical' || color === 'danger') {
    colorClasses = 'bg-red-500/20 text-red-300 border-red-500/40';
  } else if (color === 'blue' || color === 'primary' || color === 'info') {
    colorClasses = 'bg-sky-500/20 text-sky-300 border-sky-500/40';
  } else if (color === 'purple' || color === 'secondary') {
    colorClasses = 'bg-purple-500/20 text-purple-300 border-purple-500/40';
  }

  return (
    <span
      data-testid="a2ui-badge"
      className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs leading-4 font-semibold border ${colorClasses}`}
    >
      <span className="w-1.5 h-1.5 rounded-full bg-current opacity-80" />
      <span>{String(label)}</span>
    </span>
  );
}

/**
 * Material Expansion Panel / Accordion (Collapsible).
 */
function RenderExpansionPanel({
  props,
  children,
}: {
  props: Record<string, any>;
  children: React.ReactNode;
}) {
  const [expanded, setExpanded] = useState<boolean>(
    Boolean(props.expanded ?? props.isExpanded ?? props.is_expanded ?? false)
  );
  const inlineContent = props.content ?? props.body ?? props.text;
  const subtitle = props.description || props.subtitle;

  return (
    <div className="border border-[#30363d] rounded-md bg-[#161b22] overflow-hidden my-1">
      <button
        type="button"
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-3 text-left bg-[#161b22] hover:bg-[#1f242c] transition-colors cursor-pointer"
      >
        <div className="space-y-0.5">
          <div className="text-base leading-6 font-semibold text-white">{props.title || 'Details'}</div>
          {subtitle && (
            <div className="text-sm leading-5 text-gray-400">{subtitle}</div>
          )}
        </div>
        {expanded ? (
          <ChevronDown className="w-4 h-4 text-indigo-400 shrink-0" />
        ) : (
          <ChevronRight className="w-4 h-4 text-gray-400 shrink-0" />
        )}
      </button>
      {expanded && (
        <div className="p-4 bg-[#0d1117] border-t border-[#30363d] space-y-2">
          {inlineContent && (
            <pre className="p-3 rounded bg-[#161b22] border border-[#30363d] text-sm leading-5 font-mono text-emerald-300 overflow-x-auto whitespace-pre-wrap">
              {typeof inlineContent === 'string'
                ? inlineContent
                : JSON.stringify(inlineContent, null, 2)}
            </pre>
          )}
          {children}
        </div>
      )}
    </div>
  );
}

/**
 * Interactive Material Tabs component.
 */
function RenderTabs({
  props,
  children,
}: {
  props: Record<string, any>;
  children: React.ReactNode[];
}) {
  const tabList: Array<{ id?: string; label: string; content?: string; description?: string }> =
    Array.isArray(props.tabs)
      ? props.tabs.map((t: any, idx: number) =>
          typeof t === 'string' ? { id: `tab-${idx}`, label: t } : t
        )
      : [];
  const [activeIdx, setActiveIdx] = useState<number>(
    Number(props.activeTab ?? props.selectedIndex ?? 0)
  );

  const activeTabObj = tabList[activeIdx];
  const hasPerTabChildren = Array.isArray(children) && children.length === tabList.length && tabList.length > 0;

  return (
    <div className="rounded-md border border-[#30363d] bg-[#0d1117] overflow-hidden my-1">
      <div className="flex gap-1 border-b border-[#30363d] bg-[#161b22] px-2 pt-1 overflow-x-auto">
        {tabList.map((t, idx) => (
          <button
            key={t.id || idx}
            type="button"
            onClick={() => setActiveIdx(idx)}
            className={`px-4 py-2 text-sm leading-5 font-medium border-b-2 transition-colors cursor-pointer whitespace-nowrap ${
              idx === activeIdx
                ? 'border-indigo-500 text-indigo-300 bg-[#0d1117]/60 rounded-t'
                : 'border-transparent text-gray-400 hover:text-gray-200'
            }`}
          >
            {t.label}
          </button>
        ))}
      </div>
      {(activeTabObj?.content || activeTabObj?.description || (children && children.length > 0)) && (
        <div className="p-4 text-base leading-6 text-gray-300 space-y-2">
          {(activeTabObj?.content || activeTabObj?.description) && (
            <p className="text-base leading-6 text-gray-300">
              {activeTabObj.content || activeTabObj.description}
            </p>
          )}
          {hasPerTabChildren ? children[activeIdx] : children}
        </div>
      )}
    </div>
  );
}

/**
 * Material & Rich Table component.
 */
function RenderTable({
  props,
  dataModel,
}: {
  props: Record<string, any>;
  dataModel: Record<string, any>;
}) {
  let rows = props.rows || props.data || [];
  if (props.rows?.path) {
    rows = getValueByPointer(dataModel, props.rows.path) || [];
  } else if (props.data?.path) {
    rows = getValueByPointer(dataModel, props.data.path) || [];
  }

  const columns: Array<{
    id?: string;
    key?: string;
    field?: string;
    name?: string;
    dataIndex?: string;
    label?: string;
    title?: string;
    header?: string;
    headerName?: string;
  }> = props.columns || [];

  if (!Array.isArray(rows) || rows.length === 0) {
    return (
      <div className="p-3 rounded bg-[#0d1117] border border-[#30363d] text-sm leading-5 text-gray-400 text-center">
        No records available.
      </div>
    );
  }

  // Derive column headers if not explicitly specified
  const effectiveCols =
    columns.length > 0
      ? columns
      : Object.keys(rows[0] || {}).map((k) => ({ id: k, label: k }));

  return (
    <div className="rounded-md border border-[#30363d] overflow-hidden my-1 bg-[#0d1117]">
      {props.title && (
        <div className="px-4 py-2 bg-[#161b22] border-b border-[#30363d] text-base leading-6 font-semibold text-white">
          {props.title}
        </div>
      )}
      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm leading-5">
          <thead className="bg-[#161b22] border-b border-[#30363d] text-gray-300 font-semibold text-xs leading-4">
            <tr>
              {effectiveCols.map((col, idx) => (
                <th
                  key={col.id || col.key || col.field || col.name || col.dataIndex || idx}
                  className="px-4 py-2 uppercase"
                >
                  {col.label ||
                    col.title ||
                    col.header ||
                    col.headerName ||
                    col.field ||
                    col.id ||
                    col.key ||
                    col.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-[#30363d]/60 text-gray-200">
            {rows.map((row: any, rIdx: number) => (
              <tr key={rIdx} className="hover:bg-[#161b22]/50 transition-colors">
                {effectiveCols.map((col, cIdx) => {
                  const key =
                    col.id || col.key || col.field || col.name || col.dataIndex || '';
                  const cellVal =
                    row && typeof row === 'object' ? row[key] : undefined;
                  return (
                    <td key={cIdx} className="px-4 py-2">
                      {typeof cellVal === 'object' && cellVal !== null
                        ? JSON.stringify(cellVal)
                        : String(cellVal ?? '')}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * VegaChart / VegaLiteChart / InteractiveChart Component.
 * Renders title, visual chart preview (bar, arc/donut, or line/area), and expandable Vega-Lite JSON spec.
 */
const CHART_PALETTE = [
  '#6366f1', // Indigo
  '#10b981', // Emerald
  '#f59e0b', // Amber
  '#0ea5e9', // Sky
  '#a855f7', // Purple
  '#f43f5e', // Rose
  '#14b8a6', // Teal
  '#eab308', // Yellow
];

/**
 * Computes an SVG path string for a circular Pie wedge (innerRadius === 0)
 * or Donut ring sector (innerRadius > 0). Angles are in radians where
 * -Math.PI / 2 is 12 o'clock and angles increase clockwise.
 */
export function buildSvgArcPath(
  cx: number,
  cy: number,
  innerRadius: number,
  outerRadius: number,
  startAngle: number,
  endAngle: number
): string {
  const maxSpan = Math.PI * 2 - 0.0005;
  const clampedEnd =
    endAngle - startAngle >= maxSpan ? startAngle + maxSpan : endAngle;
  const largeArc = clampedEnd - startAngle > Math.PI ? 1 : 0;

  const x1 = cx + outerRadius * Math.cos(startAngle);
  const y1 = cy + outerRadius * Math.sin(startAngle);
  const x2 = cx + outerRadius * Math.cos(clampedEnd);
  const y2 = cy + outerRadius * Math.sin(clampedEnd);

  if (innerRadius <= 0) {
    return [
      `M ${cx.toFixed(2)} ${cy.toFixed(2)}`,
      `L ${x1.toFixed(2)} ${y1.toFixed(2)}`,
      `A ${outerRadius} ${outerRadius} 0 ${largeArc} 1 ${x2.toFixed(2)} ${y2.toFixed(2)}`,
      'Z',
    ].join(' ');
  }

  const x3 = cx + innerRadius * Math.cos(clampedEnd);
  const y3 = cy + innerRadius * Math.sin(clampedEnd);
  const x4 = cx + innerRadius * Math.cos(startAngle);
  const y4 = cy + innerRadius * Math.sin(startAngle);

  return [
    `M ${x1.toFixed(2)} ${y1.toFixed(2)}`,
    `A ${outerRadius} ${outerRadius} 0 ${largeArc} 1 ${x2.toFixed(2)} ${y2.toFixed(2)}`,
    `L ${x3.toFixed(2)} ${y3.toFixed(2)}`,
    `A ${innerRadius} ${innerRadius} 0 ${largeArc} 0 ${x4.toFixed(2)} ${y4.toFixed(2)}`,
    'Z',
  ].join(' ');
}

function RenderVegaChart({
  props,
  dataModel,
}: {
  props: Record<string, any>;
  dataModel: Record<string, any>;
}) {
  const [showSpec, setShowSpec] = useState(false);
  const [activeIdx, setActiveIdx] = useState<number | null>(null);

  const spec = useMemo(() => {
    const raw = props.spec || props.vegaSpec || props.chartSpec;
    if (typeof raw === 'string') {
      try {
        return JSON.parse(raw);
      } catch {
        return {};
      }
    }
    if (raw && typeof raw === 'object') return raw;
    if (props.mark || props.$schema || props.encoding) return props;
    return {};
  }, [props]);

  const title =
    props.title ||
    (typeof spec.title === 'string' ? spec.title : spec.title?.text) ||
    'Vega-Lite Visualization';
  const description = props.description || spec.description || '';

  // Extract data values from spec or props
  let values: any[] = spec.data?.values || props.data || props.values || [];
  if (spec.data?.values?.path) {
    values = getValueByPointer(dataModel, spec.data.values.path) || [];
  } else if (props.data?.path) {
    values = getValueByPointer(dataModel, props.data.path) || [];
  }

  const rawMarkType = (
    typeof spec.mark === 'string'
      ? spec.mark
      : spec.mark?.type || props.chartType || props.type || 'bar'
  ).toLowerCase();

  const specInnerRadius =
    typeof spec.mark === 'object' && spec.mark !== null
      ? Number(spec.mark.innerRadius ?? -1)
      : Number(props.innerRadius ?? -1);

  const initialMode = useMemo<'bar' | 'donut' | 'pie' | 'line'>(() => {
    const titleLower = String(title || '').toLowerCase();
    if (
      rawMarkType === 'pie' ||
      (rawMarkType === 'arc' &&
        (specInnerRadius === 0 ||
          (titleLower.includes('pie') && !titleLower.includes('donut'))))
    ) {
      return 'pie';
    }
    if (
      rawMarkType === 'donut' ||
      rawMarkType === 'arc' ||
      titleLower.includes('donut')
    ) {
      return 'donut';
    }
    if (
      rawMarkType === 'line' ||
      rawMarkType === 'area' ||
      rawMarkType === 'point' ||
      rawMarkType === 'trail'
    ) {
      return 'line';
    }
    return 'bar';
  }, [rawMarkType, specInnerRadius, title]);

  const [chartMode, setChartMode] = useState<'bar' | 'donut' | 'pie' | 'line'>(
    initialMode
  );

  useEffect(() => {
    setChartMode(initialMode);
  }, [initialMode]);

  // Compute visual chart items from values array
  const { previewItems, totalVal, niceMaxVal } = useMemo(() => {
    if (!Array.isArray(values) || values.length === 0) {
      return { previewItems: [], totalVal: 0, niceMaxVal: 100 };
    }
    const sample = values.slice(0, 8);
    const first = sample[0];
    if (!first || typeof first !== 'object') {
      return { previewItems: [], totalVal: 0, niceMaxVal: 100 };
    }

    // Prefer fields specified in encoding if available
    let labelField =
      spec.encoding?.x?.field ||
      spec.encoding?.color?.field ||
      spec.encoding?.y?.field ||
      '';
    let numField =
      spec.encoding?.y?.field ||
      spec.encoding?.theta?.field ||
      spec.encoding?.x?.field ||
      '';

    if (!numField || typeof first[numField] !== 'number') {
      numField = '';
      for (const [k, v] of Object.entries(first)) {
        if (typeof v === 'number' && !numField) numField = k;
      }
    }
    if (!labelField || labelField === numField) {
      labelField = '';
      for (const [k, v] of Object.entries(first)) {
        if (typeof v === 'string' && !labelField) labelField = k;
      }
    }

    if (!numField) {
      return { previewItems: [], totalVal: 0, niceMaxVal: 100 };
    }
    const rawMax = Math.max(...sample.map((s) => Number(s[numField]) || 0), 1);
    const niceMax =
      rawMax <= 100 && rawMax >= 70
        ? 100
        : Math.ceil(rawMax / Math.pow(10, Math.floor(Math.log10(rawMax)))) *
          Math.pow(10, Math.floor(Math.log10(rawMax)));
    const sum =
      sample.reduce((acc, s) => acc + Math.max(0, Number(s[numField]) || 0), 0) ||
      1;

    let currentAngle = -Math.PI / 2;
    const items = sample.map((item, idx) => {
      const val = Math.max(0, Number(item[numField]) || 0);
      const fraction = val / sum;
      const sweep = fraction * Math.PI * 2;
      const startAngle = currentAngle;
      const endAngle = currentAngle + sweep;
      const midAngle = startAngle + sweep / 2;
      currentAngle = endAngle;

      return {
        label:
          labelField && item[labelField] !== undefined
            ? String(item[labelField])
            : `Series ${idx + 1}`,
        value: val,
        pctOfMax: Math.min(100, Math.max(4, (val / niceMax) * 100)),
        sharePct: Math.round(fraction * 100),
        colorHex: CHART_PALETTE[idx % CHART_PALETTE.length],
        startAngle,
        endAngle,
        midAngle,
      };
    });

    return {
      previewItems: items,
      totalVal: sum,
      niceMaxVal: niceMax,
    };
  }, [values, spec]);

  const focusedItem =
    activeIdx !== null && previewItems[activeIdx]
      ? previewItems[activeIdx]
      : null;

  return (
    <div
      data-testid="a2ui-vega-chart"
      className="rounded-lg border border-indigo-500/40 bg-[#161b22] p-4 my-2 space-y-3 shadow-md"
    >
      {/* Header with Interactive Chart Mode Switcher */}
      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-[#30363d] pb-2">
        <div className="flex items-center gap-2 min-w-0">
          <BarChart2 className="w-4 h-4 text-indigo-400 shrink-0" />
          <span className="text-base leading-6 font-semibold text-white truncate">
            {title}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {/* Interactive Chart Type Switcher */}
          <div className="flex items-center rounded bg-[#0d1117] border border-[#30363d] overflow-hidden text-xs">
            {(['bar', 'donut', 'pie', 'line'] as const).map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setChartMode(m)}
                className={`px-2.5 py-1 uppercase font-mono transition-colors cursor-pointer ${
                  chartMode === m
                    ? 'bg-indigo-600 text-white font-semibold'
                    : 'text-gray-400 hover:text-gray-200'
                }`}
              >
                {m}
              </button>
            ))}
          </div>
          <button
            type="button"
            onClick={() => setShowSpec(!showSpec)}
            className="flex items-center gap-1 px-2.5 py-1 rounded bg-[#0d1117] border border-[#30363d] text-xs text-indigo-300 hover:text-white transition-colors cursor-pointer"
          >
            <Code className="w-3.5 h-3.5" />
            <span>{showSpec ? 'Hide Spec' : 'Vega Spec'}</span>
          </button>
        </div>
      </div>

      {description && <p className="text-sm leading-5 text-gray-400">{description}</p>}

      {/* 1. Circular SVG Pie Chart & Donut Chart */}
      {(chartMode === 'donut' || chartMode === 'pie') &&
        previewItems.length > 0 && (
          <div className="flex flex-col sm:flex-row items-center gap-4 pt-1">
            {/* Circular SVG Pie / Donut Canvas */}
            <div className="relative shrink-0 w-44 h-44 flex items-center justify-center">
              <svg
                viewBox="0 0 190 190"
                className="w-44 h-44 overflow-visible drop-shadow-md"
              >
                {previewItems.map((slice, idx) => {
                  const isFocused = activeIdx === idx;
                  const innerR = chartMode === 'donut' ? 46 : 0;
                  const outerR = isFocused ? 82 : 76;
                  const offsetDist = isFocused ? 5 : 0;
                  const dx = Math.cos(slice.midAngle) * offsetDist;
                  const dy = Math.sin(slice.midAngle) * offsetDist;
                  const pathData = buildSvgArcPath(
                    95 + dx,
                    95 + dy,
                    innerR,
                    outerR,
                    slice.startAngle,
                    slice.endAngle
                  );
                  const labelR = chartMode === 'donut' ? 62 : 48;
                  const labelX = 95 + dx + Math.cos(slice.midAngle) * labelR;
                  const labelY = 95 + dy + Math.sin(slice.midAngle) * labelR;

                  return (
                    <g
                      key={idx}
                      onMouseEnter={() => setActiveIdx(idx)}
                      onMouseLeave={() => setActiveIdx(null)}
                      onClick={() =>
                        setActiveIdx(activeIdx === idx ? null : idx)
                      }
                      className="cursor-pointer transition-transform"
                    >
                      <path
                        d={pathData}
                        fill={slice.colorHex}
                        stroke="#161b22"
                        strokeWidth="2"
                        opacity={
                          activeIdx === null || activeIdx === idx ? 1 : 0.6
                        }
                      >
                        <title>{`${slice.label}: ${slice.value.toLocaleString()} (${slice.sharePct}%)`}</title>
                      </path>
                      {slice.sharePct >= 8 && (
                        <text
                          x={labelX}
                          y={labelY}
                          textAnchor="middle"
                          dominantBaseline="central"
                          fill="#ffffff"
                          fontSize="10"
                          fontWeight="700"
                          className="pointer-events-none select-none drop-shadow"
                        >
                          {slice.sharePct}%
                        </text>
                      )}
                    </g>
                  );
                })}

                {/* Center Readout Inside Donut Hole */}
                {chartMode === 'donut' && (
                  <g className="pointer-events-none select-none">
                    <circle cx="95" cy="95" r="42" fill="#0d1117" />
                    <text
                      x="95"
                      y="82"
                      textAnchor="middle"
                      fill="#9ca3af"
                      fontSize="8.5"
                      fontWeight="600"
                    >
                      {focusedItem
                        ? focusedItem.label.slice(0, 14)
                        : 'TOTAL'}
                    </text>
                    <text
                      x="95"
                      y="99"
                      textAnchor="middle"
                      fill="#ffffff"
                      fontSize="14"
                      fontWeight="700"
                    >
                      {focusedItem
                        ? focusedItem.value.toLocaleString()
                        : totalVal.toLocaleString()}
                    </text>
                    <text
                      x="95"
                      y="113"
                      textAnchor="middle"
                      fill="#818cf8"
                      fontSize="9"
                      fontWeight="600"
                    >
                      {focusedItem ? `${focusedItem.sharePct}% share` : '100%'}
                    </text>
                  </g>
                )}
              </svg>
            </div>

            {/* Interactive Slice Legend */}
            <div className="flex-1 w-full grid grid-cols-1 gap-2">
              {previewItems.map((it, idx) => {
                const isSelected = activeIdx === idx;
                return (
                  <button
                    key={idx}
                    type="button"
                    onMouseEnter={() => setActiveIdx(idx)}
                    onMouseLeave={() => setActiveIdx(null)}
                    onClick={() =>
                      setActiveIdx(activeIdx === idx ? null : idx)
                    }
                    className={`flex items-center justify-between px-3 py-2 rounded border text-left text-sm leading-5 transition-colors cursor-pointer ${
                      isSelected
                        ? 'bg-indigo-600/20 border-indigo-400 text-white'
                        : 'bg-[#0d1117] border-[#30363d]/80 text-gray-200 hover:border-gray-500'
                    }`}
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <span
                        className="w-3 h-3 rounded-sm shrink-0"
                        style={{ backgroundColor: it.colorHex }}
                      />
                      <span className="truncate font-medium">{it.label}</span>
                    </span>
                    <span className="font-mono text-indigo-300 shrink-0 ml-2 text-xs">
                      {it.value.toLocaleString()} ({it.sharePct}%)
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

      {/* 2. 2D Cartesian Vertical Column Bar Chart */}
      {chartMode === 'bar' && previewItems.length > 0 && (
        <div className="pt-1">
          <svg
            viewBox="0 0 540 210"
            className="w-full h-48 overflow-visible select-none"
          >
            {/* Horizontal Y-Axis Gridlines & Tick Labels */}
            {[0, 0.25, 0.5, 0.75, 1].map((tickRatio, tIdx) => {
              const yPos = 166 - tickRatio * 136;
              const tickVal = Math.round(niceMaxVal * tickRatio);
              return (
                <g key={tIdx}>
                  <line
                    x1={44}
                    y1={yPos}
                    x2={524}
                    y2={yPos}
                    stroke={tickRatio === 0 ? '#4b5563' : '#30363d'}
                    strokeWidth={tickRatio === 0 ? '1.2' : '0.8'}
                    strokeDasharray={tickRatio === 0 ? undefined : '3,3'}
                  />
                  <text
                    x={38}
                    y={yPos + 3}
                    textAnchor="end"
                    fill="#9ca3af"
                    fontSize="9.5"
                    fontFamily="monospace"
                  >
                    {tickVal.toLocaleString()}
                  </text>
                </g>
              );
            })}

            {/* Vertical Columns & X-Axis Labels */}
            {previewItems.map((bar, idx) => {
              const slotWidth = 480 / previewItems.length;
              const barWidth = Math.min(52, Math.max(20, slotWidth * 0.56));
              const centerX = 44 + slotWidth * idx + slotWidth / 2;
              const barX = centerX - barWidth / 2;
              const barHeight = Math.max(4, (bar.value / niceMaxVal) * 136);
              const barY = 166 - barHeight;
              const isFocused = activeIdx === idx;

              return (
                <g
                  key={idx}
                  onMouseEnter={() => setActiveIdx(idx)}
                  onMouseLeave={() => setActiveIdx(null)}
                  onClick={() => setActiveIdx(activeIdx === idx ? null : idx)}
                  className="cursor-pointer"
                >
                  {/* Column Background Hover Track */}
                  <rect
                    x={centerX - slotWidth * 0.42}
                    y={26}
                    width={slotWidth * 0.84}
                    height={140}
                    rx="4"
                    fill={isFocused ? '#ffffff0a' : 'transparent'}
                  />
                  {/* Vertical Bar Column */}
                  <rect
                    x={barX}
                    y={barY}
                    width={barWidth}
                    height={barHeight}
                    rx="4"
                    fill={bar.colorHex}
                    stroke={isFocused ? '#ffffff' : 'none'}
                    strokeWidth="1.5"
                    opacity={activeIdx === null || isFocused ? 0.95 : 0.65}
                  >
                    <title>{`${bar.label}: ${bar.value.toLocaleString()}`}</title>
                  </rect>
                  {/* Value Callout Above Bar */}
                  <text
                    x={centerX}
                    y={barY - 6}
                    textAnchor="middle"
                    fill={isFocused ? '#ffffff' : '#c7d2fe'}
                    fontSize="10"
                    fontWeight="700"
                    fontFamily="monospace"
                  >
                    {bar.value.toLocaleString()}
                  </text>
                  {/* X-Axis Category Label Below Baseline */}
                  <text
                    x={centerX}
                    y={184}
                    textAnchor="middle"
                    fill={isFocused ? '#ffffff' : '#d1d5db'}
                    fontSize="10"
                    fontWeight={isFocused ? '700' : '500'}
                  >
                    {bar.label.length > 13
                      ? `${bar.label.slice(0, 12)}…`
                      : bar.label}
                  </text>
                </g>
              );
            })}
          </svg>
        </div>
      )}

      {/* 3. 2D Cartesian Line & Shaded Area Chart */}
      {chartMode === 'line' && previewItems.length > 0 && (
        <div className="pt-1">
          <svg
            viewBox="0 0 540 210"
            className="w-full h-48 overflow-visible select-none"
          >
            <defs>
              <linearGradient id="a2uiLineAreaGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="#6366f1" stopOpacity="0.42" />
                <stop offset="100%" stopColor="#6366f1" stopOpacity="0.02" />
              </linearGradient>
            </defs>

            {/* Horizontal Y-Axis Gridlines */}
            {[0, 0.25, 0.5, 0.75, 1].map((tickRatio, tIdx) => {
              const yPos = 166 - tickRatio * 136;
              const tickVal = Math.round(niceMaxVal * tickRatio);
              return (
                <g key={tIdx}>
                  <line
                    x1={44}
                    y1={yPos}
                    x2={524}
                    y2={yPos}
                    stroke={tickRatio === 0 ? '#4b5563' : '#30363d'}
                    strokeWidth={tickRatio === 0 ? '1.2' : '0.8'}
                    strokeDasharray={tickRatio === 0 ? undefined : '3,3'}
                  />
                  <text
                    x={38}
                    y={yPos + 3}
                    textAnchor="end"
                    fill="#9ca3af"
                    fontSize="9.5"
                    fontFamily="monospace"
                  >
                    {tickVal.toLocaleString()}
                  </text>
                </g>
              );
            })}

            {/* Shaded Area Polygon + Trend Polyline */}
            {(() => {
              const slotWidth = 480 / previewItems.length;
              const pts = previewItems.map((pt, idx) => {
                const x = 44 + slotWidth * idx + slotWidth / 2;
                const y = 166 - (pt.value / niceMaxVal) * 136;
                return { ...pt, x, y, idx };
              });
              const polylinePoints = pts.map((p) => `${p.x},${p.y}`).join(' ');
              const areaPath =
                pts.length > 1
                  ? `M ${pts[0].x} 166 L ` +
                    pts.map((p) => `${p.x} ${p.y}`).join(' L ') +
                    ` L ${pts[pts.length - 1].x} 166 Z`
                  : '';

              return (
                <>
                  {areaPath && (
                    <path d={areaPath} fill="url(#a2uiLineAreaGrad)" />
                  )}
                  {pts.length > 1 && (
                    <polyline
                      fill="none"
                      stroke="#6366f1"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      points={polylinePoints}
                    />
                  )}
                  {pts.map((p) => {
                    const isFocused = activeIdx === p.idx;
                    return (
                      <g
                        key={p.idx}
                        onMouseEnter={() => setActiveIdx(p.idx)}
                        onMouseLeave={() => setActiveIdx(null)}
                        onClick={() =>
                          setActiveIdx(activeIdx === p.idx ? null : p.idx)
                        }
                        className="cursor-pointer"
                      >
                        <circle
                          cx={p.x}
                          cy={p.y}
                          r={isFocused ? 6 : 4.5}
                          fill={p.colorHex}
                          stroke="#ffffff"
                          strokeWidth="1.5"
                        />
                        <text
                          x={p.x}
                          y={p.y - 9}
                          textAnchor="middle"
                          fill="#e0e7ff"
                          fontSize="9.5"
                          fontWeight="700"
                          fontFamily="monospace"
                        >
                          {p.value.toLocaleString()}
                        </text>
                        <text
                          x={p.x}
                          y={184}
                          textAnchor="middle"
                          fill="#d1d5db"
                          fontSize="10"
                        >
                          {p.label.length > 13
                            ? `${p.label.slice(0, 12)}…`
                            : p.label}
                        </text>
                      </g>
                    );
                  })}
                </>
              );
            })()}
          </svg>
        </div>
      )}

      {/* Expandable JSON Spec */}
      {showSpec && (
        <div className="pt-2 border-t border-[#30363d]">
          <pre className="p-3 rounded bg-black/60 border border-[#30363d] text-xs font-mono text-gray-300 overflow-x-auto max-h-48">
            <code>{JSON.stringify(spec, null, 2)}</code>
          </pre>
        </div>
      )}
    </div>
  );
}

const TILE_SIZE = 256;
const MIN_MAP_ZOOM = 2;
const MAX_MAP_ZOOM = 18;

/**
 * Projects geographic (lat, lng) coordinates into Web Mercator (EPSG:3857)
 * world pixel coordinates at a given integer zoom level.
 */
export function latLngToWorldPixel(
  lat: number,
  lng: number,
  zoom: number
): { x: number; y: number } {
  const clampedLat = Math.max(-85.05112878, Math.min(85.05112878, Number(lat) || 0));
  const normLng = ((((Number(lng) || 0) + 180) % 360) + 360) % 360 - 180;
  const scale = TILE_SIZE * Math.pow(2, zoom);
  const x = ((normLng + 180) / 360) * scale;
  const sinLat = Math.sin((clampedLat * Math.PI) / 180);
  const y =
    (0.5 - Math.log((1 + sinLat) / (1 - sinLat)) / (4 * Math.PI)) * scale;
  return { x, y };
}

/**
 * Inverse Web Mercator projection from world pixel coordinates (x, y)
 * back to geographic (lat, lng) at a given integer zoom level.
 */
export function worldPixelToLatLng(
  x: number,
  y: number,
  zoom: number
): { lat: number; lng: number } {
  const scale = TILE_SIZE * Math.pow(2, zoom);
  const lng = ((((x / scale) * 360) % 360) + 360) % 360 - 180;
  const clampedY = Math.max(0, Math.min(scale, y));
  const n = Math.PI - (2 * Math.PI * clampedY) / scale;
  const lat = (180 / Math.PI) * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
  return {
    lat: Math.max(-85.05112878, Math.min(85.05112878, lat)),
    lng,
  };
}

/**
 * Computes the optimal center (lat, lng) and integer zoom level to frame
 * a list of markers within a viewport of (width, height) pixels.
 */
export function computeMapFitBounds(
  markers: Array<{ lat: number; lng: number }>,
  fallbackCenter: { lat: number; lng: number },
  fallbackZoom: number,
  viewportWidth: number = 680,
  viewportHeight: number = 280
): { lat: number; lng: number; zoom: number } {
  if (!markers || markers.length === 0) {
    return {
      lat: fallbackCenter.lat,
      lng: fallbackCenter.lng,
      zoom: Math.max(MIN_MAP_ZOOM, Math.min(MAX_MAP_ZOOM, Math.round(fallbackZoom || 10))),
    };
  }
  if (markers.length === 1) {
    return {
      lat: Number(markers[0].lat) || fallbackCenter.lat,
      lng: Number(markers[0].lng) || fallbackCenter.lng,
      zoom: Math.max(MIN_MAP_ZOOM, Math.min(MAX_MAP_ZOOM, Math.round(fallbackZoom || 11))),
    };
  }

  const lats = markers.map((m) => Number(m.lat) || fallbackCenter.lat);
  const lngs = markers.map((m) => Number(m.lng) || fallbackCenter.lng);
  const minLat = Math.min(...lats);
  const maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs);
  const maxLng = Math.max(...lngs);

  const centerLat = (minLat + maxLat) / 2;
  const centerLng = (minLng + maxLng) / 2;

  for (let z = 14; z >= MIN_MAP_ZOOM; z--) {
    const p1 = latLngToWorldPixel(maxLat, minLng, z);
    const p2 = latLngToWorldPixel(minLat, maxLng, z);
    const spanX = Math.abs(p2.x - p1.x);
    const spanY = Math.abs(p2.y - p1.y);
    if (spanX <= viewportWidth * 0.82 && spanY <= viewportHeight * 0.72) {
      return { lat: centerLat, lng: centerLng, zoom: z };
    }
  }

  return { lat: centerLat, lng: centerLng, zoom: MIN_MAP_ZOOM };
}

/**
 * Interactive GoogleMap Composite Component.
 * Renders a live Web Mercator Google Maps tile viewport (Roadmap, Satellite Hybrid, Terrain)
 * with interactive pan/drag, working zoom in/out controls, fit-bounds button, and geographic pins.
 */
function RenderGoogleMap({ props }: { props: Record<string, any> }) {
  const rawMarkers: Array<{
    lat: number;
    lng: number;
    title?: string;
    label?: string;
    subtitle?: string;
    status?: string;
  }> = Array.isArray(props.markers)
    ? props.markers
    : Array.isArray(props.pins)
    ? props.pins
    : [];

  const defaultCenterLat = Number(props.center?.lat ?? rawMarkers[0]?.lat ?? 37.7749);
  const defaultCenterLng = Number(props.center?.lng ?? rawMarkers[0]?.lng ?? -122.4194);
  const defaultZoom = Number(props.zoom || 10);

  const validMarkers = useMemo(() => {
    if (rawMarkers.length === 0) {
      return [
        {
          lat: defaultCenterLat,
          lng: defaultCenterLng,
          title: props.title || 'Primary Location',
          subtitle: 'Map Center',
          status: 'ACTIVE',
        },
      ];
    }
    return rawMarkers.map((m, idx) => ({
      ...m,
      lat: Number(m.lat) || defaultCenterLat,
      lng: Number(m.lng) || defaultCenterLng,
      title: m.title || m.label || `Location ${idx + 1}`,
    }));
  }, [rawMarkers, defaultCenterLat, defaultCenterLng, props.title]);

  const initialFit = useMemo(
    () =>
      computeMapFitBounds(
        validMarkers,
        { lat: defaultCenterLat, lng: defaultCenterLng },
        defaultZoom,
        680,
        280
      ),
    [validMarkers, defaultCenterLat, defaultCenterLng, defaultZoom]
  );

  const [zoom, setZoom] = useState<number>(initialFit.zoom);
  const [center, setCenter] = useState<{ lat: number; lng: number }>({
    lat: initialFit.lat,
    lng: initialFit.lng,
  });
  const [mapLayer, setMapLayer] = useState<'m' | 'y' | 'p'>('m'); // 'm' = Roadmap, 'y' = Satellite Hybrid, 'p' = Terrain
  const [selectedIdx, setSelectedIdx] = useState<number>(0);
  const [viewportSize, setViewportSize] = useState<{ width: number; height: number }>({
    width: 680,
    height: 280,
  });
  const [dragState, setDragState] = useState<{
    startX: number;
    startY: number;
    startWorldX: number;
    startWorldY: number;
  } | null>(null);

  const containerRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const updateDimensions = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width > 100 && rect.height > 100) {
        setViewportSize({ width: Math.round(rect.width), height: Math.round(rect.height) });
      }
    };
    updateDimensions();
    if (typeof ResizeObserver !== 'undefined') {
      const observer = new ResizeObserver(updateDimensions);
      observer.observe(el);
      return () => observer.disconnect();
    }
  }, []);

  const handleZoomIn = useCallback(() => {
    setZoom((z) => Math.min(MAX_MAP_ZOOM, z + 1));
  }, []);

  const handleZoomOut = useCallback(() => {
    setZoom((z) => Math.max(MIN_MAP_ZOOM, z - 1));
  }, []);

  const handleFitAll = useCallback(() => {
    const fit = computeMapFitBounds(
      validMarkers,
      { lat: defaultCenterLat, lng: defaultCenterLng },
      defaultZoom,
      viewportSize.width,
      viewportSize.height
    );
    setCenter({ lat: fit.lat, lng: fit.lng });
    setZoom(fit.zoom);
  }, [validMarkers, defaultCenterLat, defaultCenterLng, defaultZoom, viewportSize]);

  const handleSelectMarker = useCallback(
    (idx: number, focusZoom?: boolean) => {
      setSelectedIdx(idx);
      const target = validMarkers[idx];
      if (target) {
        setCenter({ lat: target.lat, lng: target.lng });
        if (focusZoom) {
          setZoom((z) => (z < 10 ? 11 : z));
        }
      }
    },
    [validMarkers]
  );

  // Compute Web Mercator tiles covering the current viewport
  const { tiles, projectedMarkers } = useMemo(() => {
    const centerWorld = latLngToWorldPixel(center.lat, center.lng, zoom);
    const viewLeft = centerWorld.x - viewportSize.width / 2;
    const viewTop = centerWorld.y - viewportSize.height / 2;
    const numTiles = Math.pow(2, zoom);

    const minTileX = Math.floor(viewLeft / TILE_SIZE);
    const maxTileX = Math.floor((viewLeft + viewportSize.width) / TILE_SIZE);
    const minTileY = Math.floor(viewTop / TILE_SIZE);
    const maxTileY = Math.floor((viewTop + viewportSize.height) / TILE_SIZE);

    const tileList: Array<{
      key: string;
      url: string;
      left: number;
      top: number;
    }> = [];

    for (let tx = minTileX; tx <= maxTileX; tx++) {
      for (let ty = minTileY; ty <= maxTileY; ty++) {
        if (ty < 0 || ty >= numTiles) continue;
        const wrappedTx = ((tx % numTiles) + numTiles) % numTiles;
        const serverIdx = Math.abs(tx + ty) % 4;
        const url = `https://mt${serverIdx}.google.com/vt/lyrs=${mapLayer}&x=${wrappedTx}&y=${ty}&z=${zoom}&hl=en`;
        tileList.push({
          key: `${zoom}-${mapLayer}-${tx}-${ty}`,
          url,
          left: Math.round(tx * TILE_SIZE - viewLeft),
          top: Math.round(ty * TILE_SIZE - viewTop),
        });
      }
    }

    const markerList = validMarkers.map((m, idx) => {
      const mw = latLngToWorldPixel(m.lat, m.lng, zoom);
      return {
        ...m,
        idx,
        px: Math.round(mw.x - viewLeft),
        py: Math.round(mw.y - viewTop),
      };
    });

    return {
      tiles: tileList,
      projectedMarkers: markerList,
    };
  }, [center.lat, center.lng, zoom, mapLayer, viewportSize.width, viewportSize.height, validMarkers]);

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    if ((e.target as HTMLElement).closest('button')) return;
    const cw = latLngToWorldPixel(center.lat, center.lng, zoom);
    setDragState({
      startX: e.clientX,
      startY: e.clientY,
      startWorldX: cw.x,
      startWorldY: cw.y,
    });
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!dragState) return;
    const dx = e.clientX - dragState.startX;
    const dy = e.clientY - dragState.startY;
    const updated = worldPixelToLatLng(
      dragState.startWorldX - dx,
      dragState.startWorldY - dy,
      zoom
    );
    setCenter(updated);
  };

  const handleMouseUp = () => {
    if (dragState) {
      setDragState(null);
    }
  };

  const activeMarker = projectedMarkers[selectedIdx] || projectedMarkers[0];

  return (
    <div
      data-testid="a2ui-google-map"
      className="rounded-lg border border-[#30363d] bg-[#0d1117] overflow-hidden my-2 shadow-md"
    >
      {/* Top Map Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-[#161b22] border-b border-[#30363d]">
        <div className="flex items-center gap-2 text-base leading-6 font-semibold text-indigo-300">
          <MapPin className="w-4 h-4 text-rose-400 shrink-0" />
          <span>{props.title || 'Google Maps View'}</span>
        </div>
        <div className="flex items-center gap-2">
          {validMarkers.length > 1 && (
            <button
              type="button"
              onClick={handleFitAll}
              title="Reset view to fit all pins"
              className="px-2.5 py-1 rounded text-xs font-medium bg-[#0d1117] hover:bg-indigo-600/20 text-indigo-300 border border-[#30363d] hover:border-indigo-500/60 transition-colors cursor-pointer"
            >
              Fit All ({validMarkers.length} Pins)
            </button>
          )}
          <div className="flex items-center rounded border border-[#30363d] bg-[#0d1117]">
            <button
              type="button"
              onClick={handleZoomOut}
              disabled={zoom <= MIN_MAP_ZOOM}
              title="Zoom Out"
              className="p-1 text-gray-300 hover:text-white disabled:opacity-40 transition-colors cursor-pointer"
            >
              <Minus className="w-3.5 h-3.5" />
            </button>
            <span className="px-2 text-xs font-mono text-indigo-300 border-x border-[#30363d]">
              Zoom {zoom}
            </span>
            <button
              type="button"
              onClick={handleZoomIn}
              disabled={zoom >= MAX_MAP_ZOOM}
              title="Zoom In"
              className="p-1 text-gray-300 hover:text-white disabled:opacity-40 transition-colors cursor-pointer"
            >
              <Plus className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </div>

      {/* Interactive Real Google Maps Tile Viewport */}
      <div
        ref={containerRef}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onDoubleClick={handleZoomIn}
        className={`relative h-72 w-full bg-[#e5e3df] overflow-hidden select-none ${
          dragState ? 'cursor-grabbing' : 'cursor-grab'
        }`}
      >
        {/* Google Maps 256x256 Web Mercator Tiles */}
        <div className="absolute inset-0 pointer-events-none">
          {tiles.map((tile) => (
            <img
              key={tile.key}
              src={tile.url}
              alt=""
              draggable={false}
              style={{
                position: 'absolute',
                left: `${tile.left}px`,
                top: `${tile.top}px`,
                width: `${TILE_SIZE}px`,
                height: `${TILE_SIZE}px`,
                maxWidth: 'none',
              }}
              className="select-none"
            />
          ))}
        </div>

        {/* SVG Route Overlay Connecting Markers at Exact Geographic Pixel Coordinates */}
        {projectedMarkers.length > 1 && (
          <svg className="absolute inset-0 w-full h-full pointer-events-none">
            {projectedMarkers.slice(0, -1).map((m, idx) => {
              const next = projectedMarkers[idx + 1];
              return (
                <line
                  key={`route-${idx}`}
                  x1={m.px}
                  y1={m.py}
                  x2={next.px}
                  y2={next.py}
                  stroke="#4f46e5"
                  strokeWidth="2.5"
                  strokeDasharray="6,4"
                  opacity="0.85"
                />
              );
            })}
          </svg>
        )}

        {/* Google Maps Layer Switcher (Map | Satellite | Terrain) */}
        <div className="absolute top-2.5 left-2.5 z-20 flex items-center rounded-md bg-white/95 shadow-md border border-gray-300 overflow-hidden text-xs font-medium text-gray-700">
          <button
            type="button"
            onClick={() => setMapLayer('m')}
            className={`px-2.5 py-1 transition-colors cursor-pointer ${
              mapLayer === 'm'
                ? 'bg-indigo-600 text-white font-semibold'
                : 'hover:bg-gray-100 text-gray-700'
            }`}
          >
            Map
          </button>
          <button
            type="button"
            onClick={() => setMapLayer('y')}
            className={`px-2.5 py-1 border-x border-gray-300 transition-colors cursor-pointer ${
              mapLayer === 'y'
                ? 'bg-indigo-600 text-white font-semibold'
                : 'hover:bg-gray-100 text-gray-700'
            }`}
          >
            Satellite
          </button>
          <button
            type="button"
            onClick={() => setMapLayer('p')}
            className={`px-2.5 py-1 transition-colors cursor-pointer ${
              mapLayer === 'p'
                ? 'bg-indigo-600 text-white font-semibold'
                : 'hover:bg-gray-100 text-gray-700'
            }`}
          >
            Terrain
          </button>
        </div>

        {/* Plotted Google Maps Teardrop Marker Pins */}
        {projectedMarkers.map((m, idx) => {
          const isSelected = idx === selectedIdx;
          const pinTitle = m.title || m.label || `Pin ${idx + 1}`;
          // Only render pins within a generous margin of the viewport
          if (
            m.px < -120 ||
            m.px > viewportSize.width + 120 ||
            m.py < -120 ||
            m.py > viewportSize.height + 120
          ) {
            return null;
          }
          return (
            <button
              key={idx}
              type="button"
              onClick={() => handleSelectMarker(idx, false)}
              onDoubleClick={(e) => {
                e.stopPropagation();
                handleSelectMarker(idx, true);
              }}
              style={{ left: `${m.px}px`, top: `${m.py}px` }}
              className={`absolute -translate-x-1/2 -translate-y-full group cursor-pointer focus:outline-none transition-transform ${
                isSelected ? 'z-20 scale-110' : 'z-10 hover:scale-105'
              }`}
              title={`${pinTitle} (${m.lat}, ${m.lng}) — Click to select, double-click to zoom in`}
            >
              {/* Floating Pin Label Pill above the Teardrop Pin */}
              <div
                className={`mb-0.5 px-2.5 py-0.5 rounded-full text-xs font-semibold whitespace-nowrap shadow-md border transition-colors ${
                  isSelected
                    ? 'bg-gray-900 text-white border-white'
                    : 'bg-white/95 text-gray-900 border-gray-300'
                }`}
              >
                {pinTitle}
              </div>
              {/* Classic Google Maps Red / Active Indigo Teardrop Pin SVG */}
              <div className="flex justify-center">
                <svg
                  width="26"
                  height="34"
                  viewBox="0 0 26 34"
                  fill="none"
                  xmlns="http://www.w3.org/2000/svg"
                  className="drop-shadow-md"
                >
                  <path
                    d="M13 0C5.82 0 0 5.82 0 13C0 22.75 13 34 13 34C13 34 26 22.75 26 13C26 5.82 20.18 0 13 0Z"
                    fill={isSelected ? '#4f46e5' : '#ea4335'}
                    stroke="#ffffff"
                    strokeWidth="1.5"
                  />
                  <circle cx="13" cy="13" r="4.5" fill="#ffffff" />
                </svg>
              </div>
            </button>
          );
        })}

        {/* Floating Bottom-Right Google Maps Zoom Controls (+ / -) */}
        <div className="absolute bottom-6 right-2.5 z-20 flex flex-col rounded-md bg-white/95 shadow-md border border-gray-300 overflow-hidden">
          <button
            type="button"
            onClick={handleZoomIn}
            disabled={zoom >= MAX_MAP_ZOOM}
            title="Zoom In"
            className="w-7 h-7 flex items-center justify-center text-gray-700 hover:bg-gray-100 disabled:opacity-40 border-b border-gray-300 cursor-pointer"
          >
            <Plus className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={handleZoomOut}
            disabled={zoom <= MIN_MAP_ZOOM}
            title="Zoom Out"
            className="w-7 h-7 flex items-center justify-center text-gray-700 hover:bg-gray-100 disabled:opacity-40 cursor-pointer"
          >
            <Minus className="w-4 h-4" />
          </button>
        </div>

        {/* Center Coordinates & Attribution HUD */}
        <div className="absolute bottom-1.5 left-2 z-20 flex items-center gap-1.5 px-2 py-0.5 rounded bg-gray-900/80 text-xs font-mono text-gray-100 shadow">
          <Compass className="w-3.5 h-3.5 text-indigo-300" />
          <span>
            {center.lat.toFixed(4)}, {center.lng.toFixed(4)} • Drag to pan
          </span>
        </div>
        <div className="absolute bottom-1 right-2 z-20 px-2 py-0.5 rounded bg-white/85 text-xs font-sans text-gray-700 shadow-sm">
          Map data ©2026 Google
        </div>
      </div>

      {/* Selected Pin Info Bar & Interactive Location Selector Chips */}
      <div className="p-3 bg-[#161b22] border-t border-[#30363d] space-y-2">
        {activeMarker && (
          <div className="flex items-center justify-between px-3 py-2 rounded bg-[#0d1117] border border-[#30363d] text-sm">
            <div className="flex items-center gap-2 min-w-0">
              <span className="w-2 h-2 rounded-full bg-rose-500 shrink-0" />
              <span className="font-semibold text-white truncate">
                {activeMarker.title || activeMarker.label || 'Selected Location'}
              </span>
              {(activeMarker.status || activeMarker.subtitle) && (
                <span className="px-2 py-0.5 rounded bg-indigo-500/15 text-xs text-indigo-300 border border-indigo-500/30 truncate">
                  {activeMarker.status || activeMarker.subtitle}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2 shrink-0 ml-2">
              <span className="text-xs font-mono text-gray-400">
                ({activeMarker.lat.toFixed(4)}, {activeMarker.lng.toFixed(4)})
              </span>
              <button
                type="button"
                onClick={() => handleSelectMarker(selectedIdx, true)}
                className="px-2.5 py-1 rounded text-xs font-medium bg-indigo-600/25 hover:bg-indigo-600/40 text-indigo-200 border border-indigo-500/40 transition-colors cursor-pointer"
              >
                Focus Pin
              </button>
            </div>
          </div>
        )}

        {validMarkers.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {validMarkers.map((m, mIdx) => (
              <button
                key={mIdx}
                type="button"
                onClick={() => handleSelectMarker(mIdx, true)}
                className={`flex items-center gap-1.5 px-2.5 py-1 rounded text-xs border transition-colors cursor-pointer ${
                  mIdx === selectedIdx
                    ? 'bg-indigo-600/25 border-indigo-500 text-indigo-200 font-medium'
                    : 'bg-[#0d1117] border-[#30363d] text-gray-300 hover:border-gray-500'
                }`}
              >
                <span
                  className={`w-2 h-2 rounded-full ${
                    mIdx === selectedIdx ? 'bg-indigo-400' : 'bg-rose-500'
                  }`}
                />
                <span>{m.title || m.label || `Pin ${mIdx + 1}`}</span>
                <span className="text-xs font-mono text-gray-500">
                  ({m.lat}, {m.lng})
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Individual Slide Card inside a MosaicCarousel.
 * Always renders a visual hero image (using props.imageUrl / props.image / props.src
 * or falling back to a generated SVG illustration) along with title, subtitle, and action button.
 */
function RenderMosaicSlideCard({
  nodeId,
  props,
  index = 0,
  surfaceId,
  onAction,
  children,
}: {
  nodeId: string;
  props: Record<string, any>;
  index?: number;
  surfaceId: string;
  onAction: (surfaceId: string, actionPayload: any) => void;
  children?: React.ReactNode;
}) {
  const fallbackSvg = useMemo(
    () => buildSlidePlaceholderDataUri(props.title || `Slide ${index + 1}`, props.subtitle, index),
    [props.title, props.subtitle, index]
  );
  const initialImg = props.imageUrl || props.image || props.src || fallbackSvg;
  const [imgSrc, setImgSrc] = useState<string>(initialImg);

  React.useEffect(() => {
    setImgSrc(props.imageUrl || props.image || props.src || fallbackSvg);
  }, [props.imageUrl, props.image, props.src, fallbackSvg]);

  return (
    <div
      key={nodeId}
      data-testid="a2ui-mosaic-slide-card"
      className="w-56 shrink-0 rounded-lg border border-[#30363d] bg-[#161b22] overflow-hidden shadow-md hover:border-indigo-500/60 transition-all flex flex-col justify-between"
    >
      <div>
        {/* Visual Hero Image */}
        <div className="relative h-28 w-full bg-[#0d1117] border-b border-[#30363d] overflow-hidden">
          <img
            src={imgSrc}
            alt={props.title || 'Carousel Slide'}
            onError={() => {
              if (imgSrc !== fallbackSvg) {
                setImgSrc(fallbackSvg);
              }
            }}
            className="w-full h-full object-cover"
          />
          {props.badge && (
            <span className="absolute top-2 right-2 px-2 py-0.5 rounded text-xs font-semibold bg-black/70 text-indigo-300 border border-indigo-500/40">
              {props.badge}
            </span>
          )}
        </div>

        {/* Card Copy */}
        <div className="p-3 space-y-1">
          <div className="text-sm leading-5 font-semibold text-white truncate">
            {props.title || `Slide ${index + 1}`}
          </div>
          {props.subtitle && (
            <div className="text-xs leading-4 text-indigo-300 truncate">{props.subtitle}</div>
          )}
          {(props.description || props.body) && (
            <p className="text-xs leading-4 text-gray-400 line-clamp-2">
              {props.description || props.body}
            </p>
          )}
          {children}
        </div>
      </div>

      {props.action && (
        <div className="px-3 pb-3 pt-1">
          <button
            type="button"
            onClick={() => onAction(surfaceId, props.action)}
            className="w-full px-3 py-1.5 rounded bg-indigo-600/30 hover:bg-indigo-600/50 text-indigo-200 border border-indigo-500/40 text-xs font-medium transition-colors cursor-pointer"
          >
            {props.actionLabel || props.buttonText || 'Select'}
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * Interactive MosaicCarousel Component.
 * Supports child MosaicSlideCard nodes OR inline `props.items` / `props.slides`,
 * with Prev/Next navigation buttons and pagination dots.
 */
function RenderMosaicCarousel({
  props,
  childNodes,
  surfaceId,
  onAction,
  renderChildNode,
}: {
  props: Record<string, any>;
  childNodes: A2UIComponentNode[];
  surfaceId: string;
  onAction: (surfaceId: string, actionPayload: any) => void;
  renderChildNode: (childId: string) => React.ReactNode;
}) {
  const inlineItems: any[] = Array.isArray(props.items)
    ? props.items
    : Array.isArray(props.slides)
    ? props.slides
    : Array.isArray(props.cards)
    ? props.cards
    : [];

  const totalSlides = childNodes.length > 0 ? childNodes.length : inlineItems.length;
  const [activeIndex, setActiveIndex] = useState<number>(0);
  const scrollContainerRef = React.useRef<HTMLDivElement>(null);

  const scrollToSlide = (nextIdx: number) => {
    if (totalSlides === 0) return;
    const bounded = (nextIdx + totalSlides) % totalSlides;
    setActiveIndex(bounded);
    if (scrollContainerRef.current) {
      const cardWidth = 232; // w-56 (224px) + gap-2 (8px)
      scrollContainerRef.current.scrollTo({
        left: bounded * cardWidth,
        behavior: 'smooth',
      });
    }
  };

  return (
    <div
      data-testid="a2ui-mosaic-carousel"
      className="my-2 rounded-lg border border-[#30363d] bg-[#0d1117] p-4 space-y-2"
    >
      {/* Carousel Header & Prev/Next Controls */}
      <div className="flex items-center justify-between border-b border-[#30363d] pb-2">
        <div className="flex items-center gap-2">
          <ImageIcon className="w-4 h-4 text-indigo-400" />
          <h4 className="text-base leading-6 font-semibold text-white">
            {props.title || 'Featured Carousel'}
          </h4>
          {totalSlides > 0 && (
            <span className="text-xs font-mono px-2 py-0.5 rounded bg-[#161b22] text-gray-400 border border-[#30363d]">
              {activeIndex + 1} / {totalSlides}
            </span>
          )}
        </div>

        {totalSlides > 1 && (
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => scrollToSlide(activeIndex - 1)}
              title="Previous Slide"
              className="p-1 rounded bg-[#161b22] hover:bg-[#21262d] text-gray-300 hover:text-white border border-[#30363d] transition-colors cursor-pointer"
            >
              <ChevronLeft className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={() => scrollToSlide(activeIndex + 1)}
              title="Next Slide"
              className="p-1 rounded bg-[#161b22] hover:bg-[#21262d] text-gray-300 hover:text-white border border-[#30363d] transition-colors cursor-pointer"
            >
              <ChevronRight className="w-3.5 h-3.5" />
            </button>
          </div>
        )}
      </div>

      {/* Horizontal Slide Track */}
      <div
        ref={scrollContainerRef}
        className="flex gap-2 overflow-x-auto pb-2 scroll-smooth"
      >
        {childNodes.length > 0
          ? childNodes.map((child, idx) =>
              child.component === 'MosaicSlideCard' || child.type === 'MosaicSlideCard' ? (
                <RenderMosaicSlideCard
                  key={child.id}
                  nodeId={child.id}
                  props={child.properties || {}}
                  index={idx}
                  surfaceId={surfaceId}
                  onAction={onAction}
                >
                  {(child.children || []).map((grandChildId) => renderChildNode(grandChildId))}
                </RenderMosaicSlideCard>
              ) : (
                <React.Fragment key={child.id}>{renderChildNode(child.id)}</React.Fragment>
              )
            )
          : inlineItems.map((item, idx) => (
              <RenderMosaicSlideCard
                key={item.id || `inline-slide-${idx}`}
                nodeId={item.id || `inline-slide-${idx}`}
                props={item.properties || item}
                index={idx}
                surfaceId={surfaceId}
                onAction={onAction}
              />
            ))}
      </div>

      {/* Pagination Dots */}
      {totalSlides > 1 && (
        <div className="flex items-center justify-center gap-1.5 pt-1">
          {Array.from({ length: totalSlides }).map((_, idx) => (
            <button
              key={idx}
              type="button"
              onClick={() => scrollToSlide(idx)}
              aria-label={`Slide ${idx + 1}`}
              className={`h-1.5 rounded-full transition-all cursor-pointer ${
                idx === activeIndex ? 'w-4 bg-indigo-500' : 'w-1.5 bg-[#30363d] hover:bg-gray-500'
              }`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================================
// 5. Main A2UISurfaceRenderer Component
// ============================================================================

export const A2UISurfaceRenderer: React.FC<A2UISurfaceRendererProps> = ({
  payload,
  onUserAction,
}) => {
  // Parse surface messages into internal state
  const [surfaces, setSurfaces] = useState<Record<string, A2UISurfaceState>>(() => {
    return parsePayloadToSurfaces(payload);
  });

  // Re-parse when payload changes externally
  React.useEffect(() => {
    setSurfaces(parsePayloadToSurfaces(payload));
  }, [payload]);

  // Update dataModel pointer value for a given surface
  const handleUpdateDataModelValue = useCallback(
    (surfaceId: string, pointer: string, value: any) => {
      setSurfaces((prev) => {
        const surface = prev[surfaceId];
        if (!surface) return prev;
        const updatedDataModel = setValueByPointer(surface.dataModel, pointer, value);
        return {
          ...prev,
          [surfaceId]: {
            ...surface,
            dataModel: updatedDataModel,
          },
        };
      });
    },
    []
  );

  // Dispatch button action resolving context pointers against dataModel
  const handleButtonClick = useCallback(
    (surfaceId: string, actionPayload: any) => {
      const surface = surfaces[surfaceId];
      const dataModel = surface?.dataModel || {};

      const actionName =
        typeof actionPayload === 'string'
          ? actionPayload
          : actionPayload?.event?.name ||
            actionPayload?.name ||
            actionPayload?.action ||
            'action_click';

      const rawContext =
        typeof actionPayload === 'string'
          ? {}
          : actionPayload?.event?.context ||
            actionPayload?.context ||
            actionPayload?.payload ||
            {};

      const resolvedExplicit = resolveActionContext(rawContext, dataModel);
      const resolvedContext =
        Object.keys(resolvedExplicit).length > 0
          ? resolvedExplicit
          : Object.keys(dataModel).length > 0
          ? { ...dataModel }
          : {};

      onUserAction?.({
        name: actionName,
        surfaceId,
        context: resolvedContext,
      });
    },
    [surfaces, onUserAction]
  );

  // Recursive component renderer
  const renderNode = (
    surfaceId: string,
    nodeId: string,
    components: Record<string, A2UIComponentNode>,
    dataModel: Record<string, any>
  ): React.ReactNode => {
    const node = components[nodeId];
    if (!node) return null;

    const props = node.properties || {};
    const compName = node.component || node.type || 'Text';

    // Render child nodes
    const renderedChildren = (node.children || []).map((childId) =>
      renderNode(surfaceId, childId, components, dataModel)
    );

    // 1. Layout: Card / MaterialCard / Banner
    if (compName === 'Card' || compName === 'MaterialCard' || compName === 'Banner') {
      const status = props.status;
      const borderClass =
        status === 'success'
          ? 'border-emerald-500/40'
          : status === 'warning'
          ? 'border-amber-500/40'
          : status === 'error'
          ? 'border-rose-500/40'
          : 'border-indigo-500/40';

      return (
        <div
          key={node.id}
          className={`border ${borderClass} rounded-lg bg-gradient-to-b from-[#161b22] to-[#0d1117] p-4 shadow-md my-2 space-y-2`}
        >
          {(props.title || props.subtitle) && (
            <div className="border-b border-[#30363d] pb-2">
              {props.title && (
                <h3 className="text-lg leading-7 font-semibold text-white">{props.title}</h3>
              )}
              {props.subtitle && (
                <p className="text-sm leading-5 text-indigo-300">{props.subtitle}</p>
              )}
            </div>
          )}
          {(props.body || props.description) && (
            <p className="text-base leading-6 text-gray-300 whitespace-pre-wrap">
              {props.body || props.description}
            </p>
          )}
          {renderedChildren}
        </div>
      );
    }

    // 2. Layout: Column / MaterialColumn / Step
    if (compName === 'Column' || compName === 'MaterialColumn' || compName === 'Step') {
      return (
        <div key={node.id} className="flex flex-col gap-2 my-1">
          {compName === 'Step' && props.title && (
            <div className="text-base leading-6 font-semibold text-indigo-300 border-b border-[#30363d]/60 pb-1">
              {props.title}
            </div>
          )}
          {renderedChildren}
        </div>
      );
    }

    // 3. Layout: Row / MaterialRow
    if (compName === 'Row' || compName === 'MaterialRow') {
      return (
        <div key={node.id} className="flex flex-row items-center gap-2 flex-wrap my-1">
          {renderedChildren}
        </div>
      );
    }

    // 4. Layout: ExpansionPanel / MaterialExpansionPanel / Accordion
    if (
      compName === 'ExpansionPanel' ||
      compName === 'MaterialExpansionPanel' ||
      compName === 'Accordion'
    ) {
      return (
        <RenderExpansionPanel key={node.id} props={props}>
          {renderedChildren}
        </RenderExpansionPanel>
      );
    }

    // 5. Layout: Divider / MaterialDivider
    if (compName === 'Divider' || compName === 'MaterialDivider') {
      return <hr key={node.id} className="border-t border-[#30363d] my-2" />;
    }

    // 6. Content: Text / MaterialText / TextBlock / Typography / Paragraph / Label
    if (
      compName === 'Text' ||
      compName === 'MaterialText' ||
      compName === 'TextBlock' ||
      compName === 'Typography' ||
      compName === 'Paragraph' ||
      compName === 'Label'
    ) {
      return <RenderText key={node.id} props={props} dataModel={dataModel} />;
    }

    // 7. Content: Badge / MaterialBadge
    if (compName === 'Badge' || compName === 'MaterialBadge') {
      return <RenderBadge key={node.id} props={props} />;
    }

    // 8. Data Display: Table / MaterialTable / RichTable / DataTable
    if (
      compName === 'Table' ||
      compName === 'MaterialTable' ||
      compName === 'RichTable' ||
      compName === 'DataTable'
    ) {
      return (
        <RenderTable
          key={node.id}
          props={props}
          dataModel={dataModel}
        />
      );
    }

    // 9. Input: Input / MaterialInput / TextField / TextInput / NumberInput / NumberField / TextArea (Two-Way Binding)
    if (
      compName === 'Input' ||
      compName === 'MaterialInput' ||
      compName === 'TextField' ||
      compName === 'TextInput' ||
      compName === 'NumberInput' ||
      compName === 'NumberField' ||
      compName === 'TextArea'
    ) {
      const pointer =
        props.value?.path ||
        props.valuePath ||
        props.binding ||
        props.bind ||
        props.path ||
        (props.defaultValue !== undefined && node.id ? `/${node.id}` : undefined);
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value !== 'object' ? props.value : undefined) ??
          props.defaultValue ??
          ''
        : typeof props.value !== 'object'
        ? props.value ?? props.defaultValue ?? ''
        : props.defaultValue ?? '';

      const isNumber =
        compName === 'NumberInput' ||
        compName === 'NumberField' ||
        props.inputType === 'number';

      return (
        <div key={node.id} className="space-y-1 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
              {props.required && <span className="text-red-400 ml-0.5">*</span>}
            </label>
          )}
          <input
            type={isNumber ? 'number' : 'text'}
            value={currentVal}
            placeholder={props.placeholder || ''}
            disabled={props.disabled}
            onChange={(e) => {
              if (pointer) {
                const nextVal = isNumber ? Number(e.target.value) : e.target.value;
                handleUpdateDataModelValue(surfaceId, pointer, nextVal);
              }
            }}
            className="w-full px-3 py-2 rounded-md bg-[#0d1117] border border-[#30363d] text-base leading-6 text-white placeholder-gray-500 focus:outline-none focus:border-indigo-500 transition-colors"
          />
          {props.helperText && (
            <span className="text-xs leading-4 text-gray-500 block">{props.helperText}</span>
          )}
        </div>
      );
    }

    // 10. Input: Select / MaterialSelect / SelectField / ChoicePicker / Dropdown (Two-Way Binding)
    if (
      compName === 'Select' ||
      compName === 'MaterialSelect' ||
      compName === 'SelectField' ||
      compName === 'ChoicePicker' ||
      compName === 'Dropdown'
    ) {
      const pointer =
        props.value?.path ||
        props.valuePath ||
        props.binding ||
        props.bind ||
        props.path ||
        (props.defaultValue !== undefined && node.id ? `/${node.id}` : undefined);
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value !== 'object' ? props.value : undefined) ??
          props.defaultValue ??
          ''
        : typeof props.value !== 'object'
        ? props.value ?? props.defaultValue ?? ''
        : props.defaultValue ?? '';

      const options: Array<{ label: string; value: string }> = Array.isArray(props.options)
        ? props.options.map((opt: any) =>
            typeof opt === 'string' ? { label: opt, value: opt } : opt
          )
        : [];

      return (
        <div key={node.id} className="space-y-1 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
            </label>
          )}
          <select
            value={currentVal}
            disabled={props.disabled}
            onChange={(e) => {
              if (pointer) {
                handleUpdateDataModelValue(surfaceId, pointer, e.target.value);
              }
            }}
            className="w-full px-3 py-2 rounded-md bg-[#0d1117] border border-[#30363d] text-base leading-6 text-white focus:outline-none focus:border-indigo-500 transition-colors"
          >
            {props.placeholder && (
              <option value="" disabled>
                {props.placeholder}
              </option>
            )}
            {options.map((opt, idx) => (
              <option key={idx} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>
      );
    }

    // 10b. Composite / Metric: MetricView / MetricCard / StatCard / KpiCard
    if (
      compName === 'MetricView' ||
      compName === 'MetricCard' ||
      compName === 'StatCard' ||
      compName === 'KpiCard'
    ) {
      const metricLabel = props.label || props.title || node.id;
      const metricValue =
        props.value?.path
          ? getValueByPointer(dataModel, props.value.path) ?? ''
          : props.value ?? '';
      return (
        <div
          key={node.id}
          className="flex items-center justify-between px-4 py-2 rounded-md border border-[#30363d] bg-[#0d1117] my-1"
        >
          <span className="text-sm leading-5 font-medium text-gray-400">{metricLabel}</span>
          <span className="text-base leading-6 font-mono font-bold text-indigo-300">
            {String(metricValue)}
            {props.unit ? ` ${props.unit}` : ''}
          </span>
        </div>
      );
    }

    // 10c. Composite: AlarmCard / AlertCard
    if (compName === 'AlarmCard' || compName === 'AlertCard') {
      const severity = String(props.urgency || props.severity || props.status || 'INFO').toUpperCase();
      const badgeColor =
        severity.includes('CRIT') || severity.includes('ERR')
          ? 'error'
          : severity.includes('HIGH') || severity.includes('WARN')
          ? 'warning'
          : 'info';
      const detailEntries = Object.entries(props).filter(
        ([k]) => !['id', 'title', 'subtitle', 'urgency', 'severity', 'status', 'body', 'description'].includes(k)
      );
      return (
        <div
          key={node.id}
          className="border border-indigo-500/30 rounded-lg bg-[#0d1117] p-4 my-2 space-y-2"
        >
          <div className="flex items-center justify-between gap-2">
            <span className="text-base leading-6 font-semibold text-white">
              {props.title || props.id || 'Alert'}
            </span>
            <RenderBadge props={{ text: severity, color: badgeColor }} />
          </div>
          {(props.body || props.description) && (
            <p className="text-sm leading-5 text-gray-300">{props.body || props.description}</p>
          )}
          {detailEntries.length > 0 && (
            <div className="grid grid-cols-2 gap-2 pt-2 border-t border-[#30363d]/60">
              {detailEntries.map(([k, v]) => (
                <div key={k} className="text-xs leading-4">
                  <span className="text-gray-500 mr-1">{k}:</span>
                  <span className="font-mono text-gray-200">{String(v)}</span>
                </div>
              ))}
            </div>
          )}
          {renderedChildren}
        </div>
      );
    }

    // 11. Input: Slider / MaterialSlider (Two-Way Binding)
    if (compName === 'Slider' || compName === 'MaterialSlider') {
      const pointer = props.value?.path || props.binding || props.bind || props.path;
      const rawVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value === 'number' ? props.value : undefined) ??
          props.min ??
          0
        : (typeof props.value === 'number' ? props.value : undefined) ?? props.min ?? 0;
      const currentNum = Number(rawVal) || 0;

      return (
        <div key={node.id} className="space-y-1 my-1">
          <div className="flex items-center justify-between text-sm leading-5 text-gray-300">
            <span>{props.label || 'Value'}</span>
            <span className="font-mono text-indigo-300">{currentNum}</span>
          </div>
          <input
            type="range"
            min={props.min ?? 0}
            max={props.max ?? 100}
            step={props.step ?? 1}
            value={currentNum}
            disabled={props.disabled}
            onChange={(e) => {
              if (pointer) {
                handleUpdateDataModelValue(surfaceId, pointer, Number(e.target.value));
              }
            }}
            className="w-full accent-indigo-500 cursor-pointer"
          />
        </div>
      );
    }

    // 12. Input: Checkbox / MaterialCheckbox / CheckBox (Two-Way Binding)
    if (
      compName === 'Checkbox' ||
      compName === 'MaterialCheckbox' ||
      compName === 'CheckBox'
    ) {
      const pointer = props.checked?.path || props.value?.path || props.binding || props.path;
      const isChecked = pointer
        ? Boolean(
            getValueByPointer(dataModel, pointer) ??
              (typeof props.checked === 'boolean' ? props.checked : false)
          )
        : Boolean(props.checked ?? false);

      return (
        <label
          key={node.id}
          className="flex items-center gap-2 text-base leading-6 text-gray-200 cursor-pointer select-none my-1"
        >
          <input
            type="checkbox"
            checked={isChecked}
            disabled={props.disabled}
            onChange={(e) => {
              if (pointer) {
                handleUpdateDataModelValue(surfaceId, pointer, e.target.checked);
              }
            }}
            className="w-4 h-4 rounded border-[#30363d] bg-[#0d1117] text-indigo-500 focus:ring-indigo-500"
          />
          <span>{props.label || ''}</span>
        </label>
      );
    }

    // 13. Action: Button / MaterialButton
    if (compName === 'Button' || compName === 'MaterialButton') {
      const label = props.label || props.text || 'Action';
      const isSecondary = props.variant === 'outlined' || props.variant === 'secondary';

      return (
        <button
          key={node.id}
          type="button"
          disabled={props.disabled}
          onClick={() => handleButtonClick(surfaceId, props.action || props)}
          className={`px-4 py-2 rounded-md text-sm leading-5 font-medium transition-all cursor-pointer shadow-sm active:scale-95 my-1 ${
            isSecondary
              ? 'bg-[#161b22] hover:bg-[#21262d] text-gray-200 border border-[#30363d]'
              : 'bg-indigo-600 hover:bg-indigo-500 text-white'
          }`}
        >
          {label}
        </button>
      );
    }

    // 14. Composite: VegaChart / VegaLiteChart / InteractiveChart / Chart
    if (
      compName === 'VegaChart' ||
      compName === 'VegaLiteChart' ||
      compName === 'InteractiveChart' ||
      compName === 'Chart'
    ) {
      return (
        <RenderVegaChart
          key={node.id}
          props={props}
          dataModel={dataModel}
        />
      );
    }

    // 15. Stepper: Multi-Step process indicator
    if (compName === 'Stepper') {
      const steps: Array<{ id?: string; title?: string; status?: string }> = props.steps || [];
      const activeStep = Number(props.activeStep ?? 1);

      return (
        <div key={node.id} className="py-2 px-1 my-1">
          <div className="flex items-center gap-2 overflow-x-auto pb-1">
            {steps.map((st, sIdx) => {
              const stepNum = sIdx + 1;
              const isCompleted = st.status === 'completed' || stepNum < activeStep;
              const isActive = st.status === 'active' || stepNum === activeStep;

              return (
                <React.Fragment key={st.id || sIdx}>
                  <div className="flex items-center gap-2 shrink-0">
                    <span
                      className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                        isCompleted
                          ? 'bg-emerald-600 text-white'
                          : isActive
                          ? 'bg-indigo-600 text-white ring-2 ring-indigo-400/50'
                          : 'bg-[#21262d] text-gray-400 border border-[#30363d]'
                      }`}
                    >
                      {isCompleted ? '✓' : stepNum}
                    </span>
                    <span
                      className={`text-sm leading-5 whitespace-nowrap font-medium ${
                        isActive
                          ? 'text-white'
                          : isCompleted
                          ? 'text-emerald-400'
                          : 'text-gray-400'
                      }`}
                    >
                      {st.title || `Step ${stepNum}`}
                    </span>
                  </div>
                  {sIdx < steps.length - 1 && (
                    <div
                      className={`h-0.5 w-4 sm:w-6 mx-1 shrink-0 ${
                        stepNum < activeStep ? 'bg-emerald-500' : 'bg-[#30363d]'
                      }`}
                    />
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>
      );
    }

    // 16. Input: RadioButton / MaterialRadioButton / RadioGroup
    if (
      compName === 'RadioButton' ||
      compName === 'MaterialRadioButton' ||
      compName === 'RadioGroup'
    ) {
      const pointer = props.value?.path || props.binding || props.bind || props.path;
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value !== 'object' ? props.value : '') ??
          ''
        : typeof props.value !== 'object'
        ? props.value ?? ''
        : '';

      const options: Array<{ label: string; value: string }> = Array.isArray(props.options)
        ? props.options.map((opt: any) =>
            typeof opt === 'string' ? { label: opt, value: opt } : opt
          )
        : [];

      return (
        <div key={node.id} className="space-y-2 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
            </label>
          )}
          <div className="space-y-1.5 pl-1">
            {options.map((opt, idx) => (
              <label
                key={idx}
                className="flex items-center gap-2 text-base leading-6 text-gray-200 cursor-pointer select-none"
              >
                <input
                  type="radio"
                  name={`${surfaceId}-${node.id}`}
                  value={opt.value}
                  checked={String(currentVal) === String(opt.value)}
                  disabled={props.disabled}
                  onChange={(e) => {
                    if (pointer) {
                      handleUpdateDataModelValue(surfaceId, pointer, e.target.value);
                    }
                  }}
                  className="w-4 h-4 text-indigo-600 bg-[#0d1117] border-[#30363d] focus:ring-indigo-500"
                />
                <span>{opt.label}</span>
              </label>
            ))}
          </div>
        </div>
      );
    }

    // 17. Input: SlideToggle / MaterialSlideToggle / Switch
    if (
      compName === 'SlideToggle' ||
      compName === 'MaterialSlideToggle' ||
      compName === 'Switch'
    ) {
      const pointer = props.checked?.path || props.value?.path || props.binding || props.path;
      const isChecked = pointer
        ? Boolean(
            getValueByPointer(dataModel, pointer) ??
              (typeof props.checked === 'boolean' ? props.checked : false)
          )
        : Boolean(props.checked ?? false);

      return (
        <label
          key={node.id}
          className="flex items-center gap-2.5 text-base leading-6 text-gray-200 cursor-pointer select-none my-1"
        >
          <div
            onClick={() => {
              if (pointer && !props.disabled) {
                handleUpdateDataModelValue(surfaceId, pointer, !isChecked);
              }
            }}
            className={`w-8 h-4 flex items-center rounded-full p-0.5 transition-colors duration-200 ease-in-out cursor-pointer ${
              isChecked ? 'bg-indigo-600' : 'bg-[#21262d] border border-[#30363d]'
            } ${props.disabled ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            <div
              className={`bg-white w-3 h-3 rounded-full shadow-md transform transition-transform duration-200 ease-in-out ${
                isChecked ? 'translate-x-4' : 'translate-x-0'
              }`}
            />
          </div>
          <span>{props.label || ''}</span>
        </label>
      );
    }

    // 18. Input: Chips / MaterialChips
    if (compName === 'Chips' || compName === 'MaterialChips') {
      const pointer = props.value?.path || props.binding || props.bind || props.path;
      const rawVal = pointer
        ? getValueByPointer(dataModel, pointer) ?? props.value ?? []
        : props.value ?? [];
      const selectedList: string[] = Array.isArray(rawVal) ? rawVal : [];

      const chipItems: Array<{ id: string; label: string; selected?: boolean }> = Array.isArray(
        props.chips
      )
        ? props.chips
        : [];

      return (
        <div key={node.id} className="space-y-1.5 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
            </label>
          )}
          <div className="flex flex-wrap gap-2">
            {chipItems.map((chip) => {
              const isSelected =
                selectedList.includes(chip.id) ||
                selectedList.includes(chip.label) ||
                Boolean(chip.selected);

              return (
                <button
                  key={chip.id}
                  type="button"
                  disabled={props.disabled}
                  onClick={() => {
                    if (pointer) {
                      const idToToggle = chip.id || chip.label;
                      const next = selectedList.includes(idToToggle)
                        ? selectedList.filter((x) => x !== idToToggle)
                        : [...selectedList, idToToggle];
                      handleUpdateDataModelValue(surfaceId, pointer, next);
                    }
                  }}
                  className={`px-3 py-1 rounded-full text-xs leading-4 font-medium transition-colors border cursor-pointer ${
                    isSelected
                      ? 'bg-indigo-600/30 text-indigo-200 border-indigo-500'
                      : 'bg-[#161b22] text-gray-400 border-[#30363d] hover:border-gray-500'
                  }`}
                >
                  {chip.label}
                </button>
              );
            })}
          </div>
        </div>
      );
    }

    // 19. Input: Datepicker / MaterialDatepicker / DatePicker
    if (
      compName === 'Datepicker' ||
      compName === 'MaterialDatepicker' ||
      compName === 'DatePicker'
    ) {
      const pointer = props.value?.path || props.binding || props.bind || props.path;
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value !== 'object' ? props.value : '') ??
          ''
        : typeof props.value !== 'object'
        ? props.value ?? ''
        : '';

      return (
        <div key={node.id} className="space-y-1 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
            </label>
          )}
          <div className="relative">
            <input
              type="date"
              value={currentVal}
              disabled={props.disabled}
              onChange={(e) => {
                if (pointer) {
                  handleUpdateDataModelValue(surfaceId, pointer, e.target.value);
                }
              }}
              className="w-full px-3 py-2 rounded-md bg-[#0d1117] border border-[#30363d] text-base leading-6 text-white focus:outline-none focus:border-indigo-500 transition-colors cursor-pointer"
            />
          </div>
        </div>
      );
    }

    // 20. Input: Timepicker / MaterialTimepicker
    if (compName === 'Timepicker' || compName === 'MaterialTimepicker') {
      const pointer = props.value?.path || props.binding || props.bind || props.path;
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ??
          (typeof props.value !== 'object' ? props.value : '') ??
          ''
        : typeof props.value !== 'object'
        ? props.value ?? ''
        : '';

      return (
        <div key={node.id} className="space-y-1 my-1">
          {props.label && (
            <label className="text-sm leading-5 font-medium text-gray-300 block">
              {props.label}
            </label>
          )}
          <input
            type="time"
            value={currentVal}
            disabled={props.disabled}
            onChange={(e) => {
              if (pointer) {
                handleUpdateDataModelValue(surfaceId, pointer, e.target.value);
              }
            }}
            className="w-full px-3 py-2 rounded-md bg-[#0d1117] border border-[#30363d] text-base leading-6 text-white focus:outline-none focus:border-indigo-500 transition-colors cursor-pointer"
          />
        </div>
      );
    }

    // 21. Content: ProgressBar / MaterialProgressBar
    if (compName === 'ProgressBar' || compName === 'MaterialProgressBar') {
      const val = Number(props.value ?? 50);
      const maxVal = Number(props.max ?? 100);
      const pct = Math.min(100, Math.max(0, (val / maxVal) * 100));
      const label = props.label || props.title || 'Progress';

      return (
        <div
          key={node.id}
          data-testid="a2ui-progress-bar"
          className="w-full min-w-[160px] flex-1 space-y-1 my-1"
        >
          <div className="flex items-center justify-between text-xs leading-4 text-gray-300">
            <span className="font-medium">{label}</span>
            <span className="font-mono text-indigo-300">{Math.round(pct)}%</span>
          </div>
          <div className="w-full bg-[#0d1117] rounded-full h-2 overflow-hidden border border-[#30363d]">
            <div
              className="bg-indigo-500 h-full rounded-full transition-all duration-300"
              style={{ width: `${pct}%` }}
            />
          </div>
        </div>
      );
    }

    // 22. Content: ProgressSpinner / MaterialProgressSpinner
    if (compName === 'ProgressSpinner' || compName === 'MaterialProgressSpinner') {
      return (
        <div
          key={node.id}
          data-testid="a2ui-progress-spinner"
          className="inline-flex items-center gap-2 px-3 py-1.5 rounded-md bg-[#0d1117] border border-[#30363d] my-1"
        >
          <div className="w-4 h-4 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin shrink-0" />
          <span className="text-xs leading-4 text-gray-300 font-medium">
            {props.label || props.text || 'Active'}
          </span>
        </div>
      );
    }

    // 23. Layout: Tabs / MaterialTabs
    if (compName === 'Tabs' || compName === 'MaterialTabs') {
      return (
        <RenderTabs key={node.id} props={props}>
          {renderedChildren}
        </RenderTabs>
      );
    }

    // 24. Composite: GoogleMap / Map preview
    if (compName === 'GoogleMap' || compName === 'Map') {
      return <RenderGoogleMap key={node.id} props={props} />;
    }

    // 25. Composite: MosaicCarousel / Carousel
    if (compName === 'MosaicCarousel' || compName === 'Carousel') {
      const childNodes = (node.children || [])
        .map((cId) => components[cId])
        .filter(Boolean);

      return (
        <RenderMosaicCarousel
          key={node.id}
          props={props}
          childNodes={childNodes}
          surfaceId={surfaceId}
          onAction={handleButtonClick}
          renderChildNode={(childId) =>
            renderNode(surfaceId, childId, components, dataModel)
          }
        />
      );
    }

    // 26. Composite: MosaicSlideCard (when rendered standalone outside MosaicCarousel)
    if (compName === 'MosaicSlideCard') {
      return (
        <RenderMosaicSlideCard
          key={node.id}
          nodeId={node.id}
          props={props}
          surfaceId={surfaceId}
          onAction={handleButtonClick}
        >
          {renderedChildren}
        </RenderMosaicSlideCard>
      );
    }

    // 27. Composite: WorkOrderList
    if (compName === 'WorkOrderList') {
      const items = props.items || props.orders || [];
      return (
        <div
          key={node.id}
          className="rounded-lg border border-[#30363d] bg-[#0d1117] p-4 my-2 space-y-2"
        >
          <div className="flex items-center gap-2 text-base leading-6 font-semibold text-white border-b border-[#30363d] pb-2">
            <ListTodo className="w-4 h-4 text-indigo-400" />
            <span>{props.title || 'Work Orders'}</span>
          </div>
          <div className="space-y-2">
            {items.map((it: any, iIdx: number) => (
              <div
                key={it.id || iIdx}
                className="flex items-center justify-between p-3 rounded bg-[#161b22] border border-[#30363d]/60 text-sm leading-5"
              >
                <div className="space-y-0.5">
                  <div className="font-medium text-gray-200">{it.title}</div>
                  <div className="text-xs leading-4 font-mono text-gray-400">
                    {it.id} • {it.assignee}
                  </div>
                </div>
                <span className="px-2 py-0.5 rounded text-xs leading-4 font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40">
                  {it.priority}
                </span>
              </div>
            ))}
          </div>
        </div>
      );
    }

    // 28. Content: Icon / MaterialIcon
    if (compName === 'Icon' || compName === 'MaterialIcon') {
      const iconName = (props.iconName || props.name || props.icon || 'star').toLowerCase();
      const iconColor = (props.color || 'indigo').toLowerCase();
      const colorMap: Record<string, string> = {
        emerald: 'text-emerald-400 bg-emerald-500/15 border-emerald-500/30',
        green: 'text-emerald-400 bg-emerald-500/15 border-emerald-500/30',
        indigo: 'text-indigo-400 bg-indigo-500/15 border-indigo-500/30',
        amber: 'text-amber-400 bg-amber-500/15 border-amber-500/30',
        red: 'text-red-400 bg-red-500/15 border-red-500/30',
      };

      const renderLucideIcon = () => {
        if (iconName.includes('star')) return <Star className="w-3.5 h-3.5" />;
        if (iconName.includes('bolt') || iconName.includes('zap')) return <Zap className="w-3.5 h-3.5" />;
        if (iconName.includes('shield') || iconName.includes('security')) return <Shield className="w-3.5 h-3.5" />;
        if (iconName.includes('alert') || iconName.includes('warn')) return <AlertCircle className="w-3.5 h-3.5" />;
        if (iconName.includes('info')) return <Info className="w-3.5 h-3.5" />;
        if (iconName.includes('sparkle')) return <Sparkles className="w-3.5 h-3.5" />;
        return <CheckCircle2 className="w-3.5 h-3.5" />;
      };

      return (
        <span
          key={node.id}
          title={iconName}
          className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded text-xs leading-4 font-mono border ${
            colorMap[iconColor] || colorMap.indigo
          }`}
        >
          {renderLucideIcon()}
          <span>{iconName}</span>
        </span>
      );
    }

    // 29. Layout: GridList / MaterialGridList
    if (compName === 'GridList' || compName === 'MaterialGridList') {
      const cols = Number(props.columns || props.cols || 2);
      return (
        <div
          key={node.id}
          className={`grid gap-2 my-1 ${cols === 3 ? 'grid-cols-3' : cols === 1 ? 'grid-cols-1' : 'grid-cols-2'}`}
        >
          {renderedChildren}
        </div>
      );
    }

    // 30. Layout: Dialog / MaterialDialog / Modal
    if (compName === 'Dialog' || compName === 'MaterialDialog' || compName === 'Modal') {
      return (
        <div
          key={node.id}
          className="rounded-lg border border-indigo-500/40 bg-[#161b22] p-4 my-2 shadow-md space-y-2"
        >
          {props.title && (
            <div className="text-base leading-6 font-semibold text-indigo-300 border-b border-[#30363d] pb-2">
              {props.title}
            </div>
          )}
          <div>{renderedChildren}</div>
        </div>
      );
    }

    // 31. Content: Image / MaterialImage
    if (compName === 'Image' || compName === 'MaterialImage') {
      const fallbackImg = buildSlidePlaceholderDataUri(props.alt || 'A2UI Image', '', 0);
      return (
        <div key={node.id} className="my-1.5">
          <img
            src={props.src || fallbackImg}
            alt={props.alt || 'A2UI Image'}
            onError={(e) => {
              const target = e.currentTarget;
              if (target.src !== fallbackImg) {
                target.src = fallbackImg;
              }
            }}
            className="rounded border border-[#30363d] max-h-40 object-cover"
          />
        </div>
      );
    }

    // 32. Input: ButtonToggle / MaterialButtonToggle
    if (compName === 'ButtonToggle' || compName === 'MaterialButtonToggle') {
      const options: Array<{ label: string; value: string }> = props.options || [];
      const pointer = props.value?.path || props.valuePath || props.binding || props.path;
      const currentVal = pointer
        ? getValueByPointer(dataModel, pointer) ?? props.value
        : props.value;
      return (
        <div key={node.id} className="inline-flex rounded-md border border-[#30363d] bg-[#0d1117] p-0.5 my-1">
          {options.map((opt, idx) => {
            const active = currentVal === opt.value || (!currentVal && idx === 0);
            return (
              <button
                key={opt.value || idx}
                type="button"
                onClick={() => {
                  if (pointer) {
                    handleUpdateDataModelValue(surfaceId, pointer, opt.value);
                  }
                }}
                className={`px-3 py-1.5 text-sm leading-5 font-medium rounded transition-colors cursor-pointer ${
                  active
                    ? 'bg-indigo-600 text-white'
                    : 'text-gray-400 hover:text-gray-200'
                }`}
              >
                {opt.label}
              </button>
            );
          })}
        </div>
      );
    }

    // 33. Composite: RightPanelForm
    if (compName === 'RightPanelForm') {
      return (
        <div
          key={node.id}
          className="rounded-lg border border-indigo-500/30 bg-[#0d1117] p-4 my-2 space-y-2"
        >
          {props.title && (
            <div className="text-base leading-6 font-semibold text-indigo-300 border-b border-[#30363d] pb-2">
              {props.title}
            </div>
          )}
          <div className="space-y-2">{renderedChildren}</div>
        </div>
      );
    }

    // Fallback renderer for unmapped component
    return (
      <div
        key={node.id}
        className="p-3 rounded border border-[#30363d] bg-[#0d1117] text-sm leading-5 text-gray-300 my-1 space-y-1"
      >
        <div className="font-semibold text-indigo-400">{compName}</div>
        {renderedChildren}
      </div>
    );
  };

  const surfaceList = Object.values(surfaces);
  if (surfaceList.length === 0) {
    return null;
  }

  return (
    <div className="space-y-3 my-2">
      {surfaceList.map((surface) => {
        const explicitRootId =
          surface.rootId && surface.components[surface.rootId]
            ? surface.rootId
            : undefined;

        // Find all top-level root components (components not referenced as a child of any other node)
        const topLevelIds = explicitRootId
          ? [explicitRootId]
          : Object.keys(surface.components).filter(
              (id) => !surface.components[id].parentId
            );

        const effectiveRootIds =
          topLevelIds.length > 0
            ? topLevelIds
            : Object.keys(surface.components).slice(0, 1);

        return (
          <div
            key={surface.surfaceId}
            className="rounded-lg border border-indigo-500/30 bg-[#161b22]/90 p-4 shadow-lg"
          >
            {/* Header bar */}
            <div className="flex items-center justify-between pb-2 mb-3 border-b border-[#30363d]/60">
              <div className="flex items-center gap-2">
                <Layers className="w-4 h-4 text-indigo-400" />
                <span className="text-sm leading-5 font-semibold text-indigo-200 uppercase tracking-wider">
                  {surface.title || 'A2UI v0.9.1 Surface'}
                </span>
              </div>
              <span className="text-xs leading-4 font-mono px-2 py-0.5 rounded bg-black/40 text-gray-400 border border-[#30363d]">
                {surface.surfaceId}
              </span>
            </div>

            {/* Tree Render */}
            {effectiveRootIds.length > 0 ? (
              <div className="space-y-2">
                {effectiveRootIds.map((rId) =>
                  renderNode(
                    surface.surfaceId,
                    rId,
                    surface.components,
                    surface.dataModel
                  )
                )}
              </div>
            ) : (
              <div className="p-2 text-sm text-gray-400">
                Surface has no root components defined.
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

// ============================================================================
// 6. Message Stream Ingestion Logic
// ============================================================================

const STRUCTURAL_COMP_KEYS = new Set([
  'id',
  'component',
  'type',
  'properties',
  'props',
  'children',
  'parentId',
  'root',
  'isRoot',
]);

/**
 * Registers a component node (and recursively any inline object children) into
 * the surface's component dictionary.
 */
function registerComponentNode(
  surface: A2UISurfaceState,
  comp: any,
  parentId?: string
): string | null {
  if (!comp || typeof comp !== 'object') return null;

  const compType = comp.component || comp.type || 'Text';
  const compId =
    comp.id ||
    `auto-${compType.toLowerCase()}-${Object.keys(surface.components).length + 1}`;

  // Extract any top-level non-structural keys as fallback properties
  const topLevelProps: Record<string, any> = {};
  for (const [k, v] of Object.entries(comp)) {
    if (!STRUCTURAL_COMP_KEYS.has(k)) {
      topLevelProps[k] = v;
    }
  }

  // Normalize children: allow both string IDs and nested inline component objects
  // at top-level comp.children, comp.props.children, or comp.properties.children
  const rawChildren = Array.isArray(comp.children)
    ? comp.children
    : Array.isArray(comp.props?.children)
    ? comp.props.children
    : Array.isArray(comp.properties?.children)
    ? comp.properties.children
    : [];
  const childIds: string[] = [];
  for (const child of rawChildren) {
    if (typeof child === 'string') {
      childIds.push(child);
    } else if (child && typeof child === 'object') {
      const registeredChildId = registerComponentNode(surface, child, compId);
      if (registeredChildId) {
        childIds.push(registeredChildId);
      }
    }
  }

  const existing = surface.components[compId] || { id: compId, component: compType };

  surface.components[compId] = {
    ...existing,
    id: compId,
    component: compType,
    type: comp.type || compType,
    parentId: parentId || comp.parentId || existing.parentId,
    children: childIds.length > 0 ? childIds : existing.children,
    properties: {
      ...topLevelProps,
      ...(existing.properties || {}),
      ...(comp.props || {}),
      ...(comp.properties || {}),
    },
  };

  if (comp.root === true || comp.isRoot === true) {
    surface.rootId = compId;
  }

  return compId;
}

/**
 * Marks parentId on all child nodes referenced by ID across the surface.
 */
function linkParentIds(surface: A2UISurfaceState) {
  for (const node of Object.values(surface.components)) {
    if (Array.isArray(node.children)) {
      for (const childId of node.children) {
        if (surface.components[childId] && !surface.components[childId].parentId) {
          surface.components[childId].parentId = node.id;
        }
      }
    }
  }
}

/**
 * Parses raw incoming A2UI payloads and messages into a dictionary of active surfaces.
 */
export function parsePayloadToSurfaces(payload: any): Record<string, A2UISurfaceState> {
  const result: Record<string, A2UISurfaceState> = {};
  if (!payload) return result;

  const normalizedPayload = normalizeStandaloneA2UIPayload(payload) || payload;

  // Flatten messages array
  let messages: any[] = [];
  if (Array.isArray(normalizedPayload)) {
    messages = normalizedPayload;
  } else if (Array.isArray(normalizedPayload.messages)) {
    messages = normalizedPayload.messages;
  } else if (typeof normalizedPayload === 'object') {
    messages = [normalizedPayload];
  }

  for (const msg of messages) {
    if (!msg || typeof msg !== 'object') continue;

    // 1. createSurface
    if (msg.createSurface) {
      const info = msg.createSurface;
      const sId = info.surfaceId || 'default_surface';
      result[sId] = {
        surfaceId: sId,
        catalog: info.catalog || info.catalogId,
        title: info.title,
        rootId: info.rootId || info.rootComponentId,
        components: {},
        dataModel: {},
      };
    }

    // 2. updateComponents
    if (msg.updateComponents) {
      const update = msg.updateComponents;
      const sId = update.surfaceId || Object.keys(result)[0] || 'default_surface';
      if (!result[sId]) {
        result[sId] = {
          surfaceId: sId,
          components: {},
          dataModel: {},
        };
      }

      if (update.rootId || update.rootComponentId) {
        result[sId].rootId = update.rootId || update.rootComponentId;
      }

      const componentList: any[] = Array.isArray(update.components)
        ? update.components
        : typeof update.components === 'object' && update.components !== null
        ? Object.values(update.components)
        : [];

      for (const comp of componentList) {
        registerComponentNode(result[sId], comp);
      }
      linkParentIds(result[sId]);
    }

    // 3. updateDataModel
    if (msg.updateDataModel) {
      const update = msg.updateDataModel;
      const sId = update.surfaceId || Object.keys(result)[0] || 'default_surface';
      if (!result[sId]) {
        result[sId] = {
          surfaceId: sId,
          components: {},
          dataModel: {},
        };
      }

      if (update.path && update.value !== undefined) {
        result[sId].dataModel = setValueByPointer(
          result[sId].dataModel,
          update.path,
          update.value
        );
      } else if (update.data && typeof update.data === 'object') {
        result[sId].dataModel = {
          ...result[sId].dataModel,
          ...update.data,
        };
      }
    }

    // 4. deleteSurface
    if (msg.deleteSurface) {
      const sId = msg.deleteSurface.surfaceId || msg.deleteSurface;
      if (typeof sId === 'string') {
        delete result[sId];
      }
    }

    // 5. Direct surface object without createSurface wrapper
    if (msg.surfaceId && (msg.components || msg.rootId || msg.dataModel)) {
      const sId = msg.surfaceId;
      if (!result[sId]) {
        result[sId] = {
          surfaceId: sId,
          title: msg.title,
          catalog: msg.catalog || msg.catalogId,
          rootId: msg.rootId,
          components: {},
          dataModel: msg.dataModel || {},
        };
      }

      const compList = Array.isArray(msg.components)
        ? msg.components
        : typeof msg.components === 'object' && msg.components !== null
        ? Object.values(msg.components)
        : [];

      for (const c of compList) {
        registerComponentNode(result[sId], c);
      }
      linkParentIds(result[sId]);
    }
  }

  return result;
}

export default A2UISurfaceRenderer;
